model.letu_bq_dbt.int__yd_ad_cost.raw_code:
{{
    config(
        materialized="incremental",
        partition_by={"field": "cost_date"},
        incremental_strategy="insert_overwrite",
    )
}}

with
    mobile_ad_ids_cte as (
        select distinct ad_id
        from {{ ref('stg__yd_ad') }}
        where
            {{ product.where("insert_date") }} and
            length(ad_url) = 0
    ),
    result as (
        select
            if(
                res.ad_id is not null
                or costs.campaign_type = 'MOBILE_APP_CAMPAIGN'
                or costs.account_name = 'analytics-mtrendo1',
                'yandexdirect_int',
                costs.utm_source
            ) as utm_source,
            if(
                res.ad_id is not null
                or costs.campaign_type = 'MOBILE_APP_CAMPAIGN'
                or costs.account_name = 'analytics-mtrendo1',
                'appsflyer',
                costs.utm_medium
            ) as utm_medium,
            costs.* except (utm_source, utm_medium)
        from {{ ref('stg__yd_cost') }} costs
        left join mobile_ad_ids_cte as res on costs.ad_id = res.ad_id
        where {{ product.where("cost_date") }}
    )

select *
from result

