    result as (
        select
            cost_date,
            {{ product.basic_columns() }},
            {{ dbt_utils.generate_surrogate_key(var("product").get("basic_columns") + ["cost_date"]) }} as row_id,
            sum(cost) as cost
        from
            data
            {{ dbt_utils.group_by(2 + var("product").get("basic_columns") | length) }}
    )
select *
from result

model.product.int__user_ids_all.raw_code:
{{
    config(
        materialized="table",
        force_on_cluster=adapter.type() == "clickhouse",
        enabled=(var("identifiers").get("tables", []) | length) > 0,
    )
}}
{% set max_count = var("identifiers").get("max_count", 50) %}

{% set relations = [] %}
{% for table_name in var("identifiers").get("tables", []) %}

    -- Проверяем, что имя модели соответствует ожидаемому имени
    {% if not table_name.startswith(("int__", "stg__")) or not table_name.endswith(
        "_user_ids"
    ) %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ table_name
                ~ ". Should be int__table_name_user_ids"
            )
        }}
    {% endif %}
    {{ relations.append(ref(table_name)) or "" }}
{% endfor %}
with

    {% if adapter.type() == "clickhouse" %}
        data as (
            {{
                product.union_relations(
                    relations,
                    include=["ids"],
                    source_column_name=None,
                )
            }}
        ),
        valid_ids as (
            select arrayJoin(ids) as id_element, COUNT(*) as id_count
            from data
            group by id_element
            having id_count between 1 and {{ max_count }}
        ),
        result as (
            select distinct
                assumeNotNull(ids[1]) as x,
                assumeNotNull(arrayJoin(arraySlice(ids, 2, length(ids) - 1))) as y
            from data
            where arrayAll(y -> y in (select id_element from valid_ids), ids)
        )
    {% elif adapter.type() == "bigquery" %}
        data as (
            {{
                product.union_relations(
                    relations,
                    include=["x", "y"],
                    source_column_name=None,
                )
            }}
        ),
        all_ids as (
            select x as id
            from data
            union all
            select y as id
            from data
        ),
        valid_ids as (
            select id, COUNT(*) as id_count
            from all_ids
            group by id
            having id_count between 1 and {{ max_count }}
        ),
        result as (
            select x, y
            from data
            where x in (select id from valid_ids) and y in (select id from valid_ids)

        )
    {% endif %}
select *
from result

model.product.int__user_ids_dict.raw_code:
{{
    config(
        order_by=("id"),
        materialized="table",
        enabled=(var("identifiers").get("tables", []) | length) > 0,
    )
}}
with
    ids as (

        select x as id
        from {{ ref("int__user_ids_all") }}
        union all
        select y as id
        from {{ ref("int__user_ids_all") }}
    ),
    counted as (select id, COUNT(*) as freq from ids group by id order by freq DESC),
    result as (
        {% if adapter.type() == "clickhouse" %}
            select
                assumeNotNull(id) as id,
                toUInt32(rowNumberInAllBlocks() - 1) as id_uint32
            from counted
            order by id_uint32
        {% elif adapter.type() == "bigquery" %}
            select id, row_number() over (order by freq desc) as id_uint32 from counted
        {% endif %}

    )
select *
from result

