{% macro cost_monitoring(sheet, tables) %}

{% if execute %}
{%- call statement('min_max_dates', fetch_result=True) -%}
    select
        min(month) as min_date,
        LAST_DAY(max(date_trunc(month, month)),month) as max_date,
    from 
        {{ sheet }}
{%- endcall -%}

{%- set min_max_dates = load_result('min_max_dates')['data'][0] -%}
{% else %}
{%- set min_max_dates = ['',''] -%}
{% endif %}

with reference_data as (
    select 
        date_trunc(month,month) as month, 
        source, 
        medium, 
        round(sum(cost)) as cost 
    from 
        {{ sheet }}
    group by 1,2,3
),
    {%- for source in tables %}
 {{source.name}}_data as (
    with 
    {% for source_table in source.sources %}
      {{source_table.name}} as (
        select
            date_trunc({{source_table.date_field}}, month) as month,
            {% if source_table.source_alias %}"{{source_table.source_alias}}"{% else %}{{source_table.source}}{% endif %} as source,
            {% if source_table.medium_alias %}"{{source_table.medium_alias}}"{% else %}{{source_table.medium}}{% endif %} as medium,
            round(sum({{source_table.cost_field}}){% if not source_table.with_vat %}*1.2 {% endif %}) as {{source.name}}_cost
        from
            {{source_table.table}}
        where 
        {{source_table.cost_field}} > 0 AND
        {% if source_table.sharded %}
            _table_suffix between 
            format_date("%Y%m%d", "{{ min_max_dates[0] }}") and
            format_date("%Y%m%d", "{{ min_max_dates[1] }}")


        {% else %}
            {{source_table.date_field}} between 
            "{{ min_max_dates[0] }}" and
            "{{ min_max_dates[1] }}"
        {% endif %}
        group by 1,2,3

      ) {%- if not loop.last -%} , {% endif %}

    {% endfor %}
    {% for source_table in source.sources %}
        select * from {{source_table.name}}
        {% if not loop.last %}
            union all
        {% endif %}

    {% endfor %}
),
    {% endfor %}

combined_result as (
    select * from reference_data
    {% for source in tables %}
    full outer join {{source.name}}_data
    using (month, source, medium)
    {% endfor %}
)
select
    date_trunc(month,month) as month, 
    source, 
    medium, 
    cost as reference_cost,
    {% for source in tables %}
    {{source.name}}_cost,
    {% if loop.previtem %}
    round(safe_divide(({{source.name}}_cost-{{loop.previtem.name}}_cost)*100,{{loop.previtem.name}}_cost),1)||"%" as {{loop.previtem.name}}_delta,      
    {% endif %}
    round(safe_divide(({{source.name}}_cost-cost)*100,cost),1)||"%" as {{source.name}}_ref_delta,
    {% endfor %}

from
    combined_result
order by 1 desc,4 desc,3,2
