    {# Step 3: Adjust calc_depth. If calc_depth is 0, assign a fallback value (e.g., product.max_calc_depth) #}
    {% if calc_depth == 0 %}
        {%- set calc_depth = var("product", {}).get("max_calc_depth", 7) | int -%}
    {% endif %}

    {# Compute the initial from_date as to_date minus calc_depth days #}
    {% set from_date = to_date - dt.timedelta(days=calc_depth) %}

    {# Step 4: If not an incremental run, return the computed dates immediately #}
    {% if not is_incremental() %}
        {% set result = {"from": from_date, "to": to_date, "is_updated": false} %}
        {%- if execute -%}
            {{
                log(
                    "Full refresh " ~ this ~ " from " ~ from_date ~ " to " ~ to_date,
                    true,
                )
            }}
        {%- endif -%}
        {{ return(result) }}
    {% endif %}

    {# Step 5: For incremental runs, query the target for the maximum date in the date_column #}
    {% set res = run_query(max_date_query) %}
    {% if res is none %} {% set max_date_value = none %}
    {% else %}
        {# We assume the first row contains our result #}
        {% set row = res.rows[0] %} {% set max_date_value = row["max_date"] %}
    {% endif %}

    {# Step 6: If a max_date exists and is later than our computed from_date, update from_date to max_date + 1 day #}
    {% if max_date_value and max_date_value > from_date %}
        {% set from_date = max_date_value + dt.timedelta(days=1) %}
    {% endif %}
    {% if min_processing_interval > 0 %}
        {% set min_allowed_from_date = to_date - dt.timedelta(
            days=min_processing_interval
        ) %}
        {% if from_date > min_allowed_from_date %}
            {% set from_date = min_allowed_from_date %}
        {% endif %}
    {% endif %}
    {% if from_date > to_date %}
        {% set result = {"from": to_date, "to": to_date, "is_updated": true} %}
        {%- if execute -%}
            {{
                log(
                    "Table " ~ this ~ " up to date " ~ to_date,
                    true,
                )
            }}
        {%- endif -%}
        {{ return(result) }}

    {% endif %}

    {# Final: Return the computed interval #}
    {% set result = {"from": from_date, "to": to_date, "is_updated": false} %}
    {%- if execute -%}
        {{
            log(
                "Incremental run " ~ this ~ " from " ~ from_date ~ " to " ~ to_date,
                true,
            )
        }}
    {%- endif -%}
    {{ return(result) }}
{% endmacro %}

