macro.product.clean_temp_tables.macro_sql:
{% macro clean_temp_tables(type=None, config_var="dbt_cleanup") %}

    {# ----------------------------
      Vars contract (optional):
        vars:
          dbt_cleanup:
            patterns: ['%__dbt_new_data_%', ...]
            regex_patterns: ['.*_tmp_[0-9]{8}_[0-9]{6}_[0-9]+$', ...]   # optional override
            exclude_patterns: ['%_tmp_keep_%', ...]
            type: optional (dry_run|clean|disabled)  # overridden by macro arg

      example run:
        dbt run-operation clean_temp_tables --args '{"type":"dry_run"}'
        dbt run-operation clean_temp_tables --args '{"type":"clean"}'
        dbt run-operation clean_temp_tables --args '{"type":"disabled"}'
    ----------------------------- #}
    {% set cfg = var(config_var, {}) %}

    {# ---- resolve requested type (macro arg > vars.type) ---- #}
    {% set requested = type if type is not none else cfg.get("type", none) %}
    {% if requested is not none %} {% set requested = requested | lower %} {% endif %}

    {# ---- mode resolution with CI priority ---- #}
    {% if target.name == "ci_prod" %} {% set mode = "clean" %}
    {% elif requested == "disabled" %} {% set mode = "disabled" %}
    {% elif requested == "clean" %} {% set mode = "clean" %}
    {% else %} {% set mode = "dry_run" %}
    {% endif %}

    {{
        log(
            "ℹ clean_temp_tables: target="
            ~ target.name
            ~ " | requested="
            ~ (requested if requested is not none else "null")
            ~ " => mode="
            ~ mode,
            info=True,
        )
    }}
    {{
        log(
            "   modes: dry_run=log only | clean=drop tables | disabled=no execution",
            info=True,
        )
    }}

    {# Hook-safe: always render a valid SQL statement so on-run-end never sends None #}
    {% set noop_sql = "/* clean_temp_tables noop */ SELECT 1" %}

    {% if mode == "disabled" %}
        {{
            log(
                "🚫 Cleanup disabled — skipping (noop SQL will be executed by hook)",
                info=True,
            )
        }}
        {{ noop_sql }}
    {% else %}

        {# ---- cluster settings from profiles.yml (target.*) ---- #}
        {% set _cluster_mode_raw = (
            target.cluster_mode if target.cluster_mode is defined else false
        ) %}
        {% set _cluster_name = none %}

        {% if target.cluster is defined %} {% set _cluster_name = target.cluster %}
        {% elif target.cluster_name is defined %}
            {% set _cluster_name = target.cluster_name %}
        {% endif %}

        {% set _cm = _cluster_mode_raw | string | lower %}
        {% set on_cluster = (
            (_cm in ["1", "true", "yes", "y", "on", "enabled", "enable"])
            and (_cluster_name is not none)
            and ((_cluster_name | string | length) > 0)
        ) %}

        {% if on_cluster %}
            {% set cluster_clause = " ON CLUSTER " ~ _cluster_name %}
            {{ log("🧩 Cluster mode enabled: " ~ _cluster_name, info=True) }}
        {% else %} {% set cluster_clause = "" %}
        {% endif %}

        {# ---- read patterns (LIKE default) ---- #}
        {% set patterns = cfg.get("patterns", ["%__dbt_new_data_%"]) %}
        {% set exclude_patterns = cfg.get("exclude_patterns", []) %}

        {# normalize to lists #}
        {% if patterns is string %} {% set patterns = [patterns] %}
        {% endif %}
        {% if exclude_patterns is string %}
            {% set exclude_patterns = [exclude_patterns] %}
        {% endif %}

        {# If patterns is empty, keep hook-safe behavior #}
        {% if patterns | length == 0 %}
            {{
                log(
                    "⚠ Cleanup skipped: patterns is empty (noop SQL will be executed by hook)",
                    info=True,
                )
            }}
            {{ noop_sql }}
        {% else %}

            {# ----------------------------
               ✅ OUT-OF-THE-BOX REGEX DEFAULT + OPTIONAL OVERRIDE
               If dbt_cleanup.regex_patterns is not provided, default protected tmp regex will be used.
               If provided, it will override the default.
            ----------------------------- #}
            {% set default_regex_patterns = [] %}
            {% set regex_patterns = cfg.get("regex_patterns", default_regex_patterns) %}

            {% if regex_patterns is string %}
                {% set regex_patterns = [regex_patterns] %}
            {% endif %}

            {# Build WHERE include: (LIKE OR match) #}
            {% set include_clauses = [] %}

            {% for p in patterns %}
                {% do include_clauses.append("name LIKE '" ~ p ~ "'") %}
            {% endfor %}

            {% for r in regex_patterns %}
                {% do include_clauses.append("match(name, '" ~ r ~ "')") %}
            {% endfor %}

            {% set where_like = "(" ~ (include_clauses | join(" OR ")) ~ ")" %}

            {# Build excludes AND NOT (...) #}
            {% set where_exclude = "" %}
            {% if exclude_patterns | length > 0 %}
                {% set ex_clauses = [] %}
                {% for p in exclude_patterns %}
                    {% do ex_clauses.append("name LIKE '" ~ p ~ "'") %}
                {% endfor %}
                {% set where_exclude = (
                    " AND NOT (" ~ (ex_clauses | join(" OR ")) ~ ")"
                ) %}
            {% endif %}

            {# Query source: local system.tables OR clusterAllReplicas(...) #}
            {% if on_cluster %}
                {% set from_clause = (
                    "clusterAllReplicas('"
                    ~ _cluster_name
                    ~ "', system, tables)"
                ) %}
            {% else %} {% set from_clause = "system.tables" %}
            {% endif %}

            {% set query %}
            WITH candidates AS (
                SELECT
                    {% if on_cluster %} hostName() AS host, {% endif %}
                    database,
                    name,
                    engine,
                    total_rows,
                    total_bytes AS bytes
                FROM {{ from_clause }}
                WHERE {{ where_like }}
                  {{ where_exclude }}
                  AND database NOT IN ('system', 'information_schema')
            )
            SELECT
                {% if on_cluster %} host, {% endif %}
                database,
                name,
                engine,
                total_rows,
                formatReadableSize(bytes) AS size,
                bytes AS total_bytes
            FROM candidates
            ORDER BY bytes DESC
            {% endset %}

            {# Hook-safe compile phase: render noop SQL #}
            {% if not execute %} {{ noop_sql }}
            {% else %}

                {% set results = run_query(query) %}

                {% if results is none or results.rows | length == 0 %}
                    {{ log("✔ No matching tables found", info=True) }} {{ noop_sql }}
                {% else %}

                    {# ---- Deduplicate tables across hosts (cluster query returns repeats) ---- #}
                    {% set unique_tables = [] %}
                    {% set unique_hosts = [] %}

                    {% for row in results.rows %}
                        {% if on_cluster %}
                            {% set host = row[0] %}
                            {% set db = row[1] %}
                            {% set tbl = row[2] %}
                        {% else %}
                            {% set host = none %}
                            {% set db = row[0] %}
                            {% set tbl = row[1] %}
                        {% endif %}

                        {% set full_name = (
                            adapter.quote(db) ~ "." ~ adapter.quote(tbl)
                        ) %}

                        {% if full_name not in unique_tables %}
                            {% do unique_tables.append(full_name) %}
                        {% endif %}

                        {% if on_cluster and host is not none and host not in unique_hosts %}
                            {% do unique_hosts.append(host) %}
                        {% endif %}
                    {% endfor %}

                    {% if mode == "dry_run" %}
                        {% set printable_query = query | replace("\n\n", "\n") | trim %}
                        {{ log("📋 DRY RUN QUERY:", info=True) }}
                        {{ log(printable_query, info=True) }}
                        {{
                            log(
                                "⚠ DRY RUN: candidates ("
                                ~ (unique_tables | length)
                                ~ ")"
                                ~ (
                                    ", hosts=" ~ (unique_hosts | length)
                                    if on_cluster
                                    else ""
                                )
                                ~ ":",
                                info=True,
                            )
                        }}
                    {% else %}
                        {{
                            log(
                                "⚠ CLEAN: will drop ("
                                ~ (unique_tables | length)
                                ~ ")"
                                ~ (
                                    ", hosts=" ~ (unique_hosts | length)
                                    if on_cluster
                                    else ""
                                )
                                ~ ":",
                                info=True,
                            )
                        }}
                    {% endif %}

                    {# ---- Detailed logging ---- #}
                    {% for row in results.rows %}
                        {% if on_cluster %}
                            {{
                                log(
                                    " - host="
                                    ~ row[0]
                                    ~ " | "
                                    ~ row[1]
                                    ~ "."
                                    ~ row[2]
                                    ~ " | engine="
                                    ~ row[3]
                                    ~ " | rows="
                                    ~ row[4]
                                    ~ " | size="
                                    ~ row[5],
                                    info=True,
                                )
                            }}
                        {% else %}
                            {{
                                log(
                                    " - "
                                    ~ row[0]
                                    ~ "."
                                    ~ row[1]
                                    ~ " | engine="
                                    ~ row[2]
                                    ~ " | rows="
                                    ~ row[3]
                                    ~ " | size="
                                    ~ row[4],
                                    info=True,
                                )
                            }}
                        {% endif %}
                    {% endfor %}

                    {% if mode == "dry_run" %} {{ noop_sql }}
                    {% else %}

                        {# ---- DROP (local or ON CLUSTER) using unique list ---- #}
                        {% set drop_sql %}
                            DROP TABLE IF EXISTS {{ unique_tables | join(', ') }}{{ cluster_clause }}
                        {% endset %}

                        {{
                            log(
                                "🧹 Dropping "
                                ~ (unique_tables | length)
                                ~ " tables"
                                ~ (
                                    " ON CLUSTER " ~ _cluster_name
                                    if on_cluster
                                    else ""
                                ),
                                info=True,
                            )
                        }}
                        {% do run_query(drop_sql) %}
                        {{ noop_sql }}

                    {% endif %}
                {% endif %}
            {% endif %}
        {% endif %}
    {% endif %}

{% endmacro %}

macro.product.check_partitioned_models_f.macro_sql:
{% macro check_partitioned_models_freshness(
    from_date, to_date=none, projects=[], percentile=95
) %}

    {% set effective_to_date %}
        {% if to_date is none %}
            date_sub(current_date(), interval 1 day)
        {% else %}
            date('{{ to_date }}')
        {% endif %}
    {% endset %}

    {% set effective_from_date %}
        date('{{ from_date }}')
    {% endset %}

    {% set models = [] %}

    {% for unique_id, node in graph.get("nodes", {}).items() %}
        {% if node.resource_type == "model" and node.package_name in projects and node.config.materialized != "view" and node.config.materialized != "ephemeral" %}
            {% do models.append(node) %}
        {% endif %}
    {% endfor %}

    {% set ordered_models = (
        models
        | sort(attribute="depends_on.nodes|length")
        | sort(attribute="name")
    ) %}

    {% set ns = namespace(has_previous_relation=false) %}

    with
        expected_days as (
            select day
            from
                unnest(
                    generate_date_array(
                        {{ effective_from_date }}, {{ effective_to_date }}
                    )
                ) as day
        ),

        model_checks as (

            {% for model in ordered_models %}

                {% set relation = adapter.get_relation(
                    database=model.database,
                    schema=model.schema,
                    identifier=model.alias,
                ) %}

                {% if relation is not none %}

                    {% set partitions_relation %}
                    `{{ model.database }}.{{ model.schema }}.INFORMATION_SCHEMA.PARTITIONS`
                    {% endset %}

                    {% if ns.has_previous_relation %}
                        union all
                    {% endif %}

                    {% set ns.has_previous_relation = true %}

                    select
                        '{{ model.package_name }}' as package_name,
                        '{{ model.database }}' as project_name,
                        '{{ model.name }}' as model_name,

                        {{ model.depends_on.nodes | length }} as level,

                        (
                            select timestamp_millis(last_modified_time)
                            from `{{ model.database }}.{{ model.schema }}.__TABLES__`
                            where table_id = '{{ model.alias }}'
                        ) as table_last_modified_at,

                        not exists (
                            select 1
                            from expected_days d
                            left join
                                (
                                    select
                                        parse_date(
                                            '%Y%m%d', partition_id
                                        ) as partition_date,
                                        total_rows
                                    from {{ partitions_relation }}
                                    where
                                        table_name = '{{ model.alias }}'
                                        and partition_id
                                        not in ('__NULL__', '__UNPARTITIONED__')
                                        and regexp_contains(partition_id, r'^\d{8}$')
                                ) p
                                on d.day = p.partition_date
                            where p.partition_date is null
                        ) as is_updated,

                        (
                            select count(*)
                            from {{ partitions_relation }}
                            where
                                table_name = '{{ model.alias }}'
                                and partition_id
                                not in ('__NULL__', '__UNPARTITIONED__')
                                and regexp_contains(partition_id, r'^\d{8}$')
                                and parse_date('%Y%m%d', partition_id)
                                between {{ effective_from_date }}
                                and {{ effective_to_date }}
                                and total_rows > 0
                        ) as partitions_with_data_count

                {% endif %}

            {% endfor %}

        )

    select
        package_name,
        project_name,
        model_name,
        case

            when table_last_modified_at is null
            then null

            when
                timestamp_diff(current_timestamp(), table_last_modified_at, second) < 60

            then
                concat(

                    cast(
                        timestamp_diff(
                            current_timestamp(), table_last_modified_at, second
                        ) as string
                    ),

                    ' seconds ago'

                )

            when
                timestamp_diff(current_timestamp(), table_last_modified_at, minute) < 60

            then
                concat(

                    cast(
                        timestamp_diff(
                            current_timestamp(), table_last_modified_at, minute
                        ) as string
                    ),

                    ' minutes ago'

                )

            when timestamp_diff(current_timestamp(), table_last_modified_at, hour) < 24

            then
                concat(

                    cast(
                        timestamp_diff(
                            current_timestamp(), table_last_modified_at, hour
                        ) as string
                    ),

                    ' hours ago'

                )

            when timestamp_diff(current_timestamp(), table_last_modified_at, day) < 30

            then
                concat(

                    cast(
                        timestamp_diff(
                            current_timestamp(), table_last_modified_at, day
                        ) as string
                    ),

                    ' days ago'

                )

            else
                concat(

                    cast(
                        timestamp_diff(
                            current_timestamp(), table_last_modified_at, day
                        ) as string
                    ),

                    ' days ago'

                )

        end as table_updated_ago,
        is_updated,
        partitions_with_data_count
    from model_checks
    order by level, model_name

{% endmacro %}

