macro.product.create_session_tables.macro_sql:
{% macro create_session_tables() %}
    {% if execute %}
        {{
            log(
                "Creating sharded tables...",
                true,
            )
        }}
    {% endif %}
    for view_query in (
        with

            holoway_session_dates as (
                select
                    format_date("%Y%m%d", session_date) as table_date,
                    '{{var("sessions")["holoway_dataset"]}}.HOLOWAY_Sessions_'
                    || format_date("%Y%m%d", session_date) as table_name,
                    count(1) as session_count
                from `{{target.database}}.{{target.schema}}.holoway_sessions`
                group by 1, 2
            ),
            existing_tables as (
                select _table_suffix as table_date, count(1) as session_count
                from `{{var("sessions")["holoway_dataset"]}}.HOLOWAY_Sessions_*`
                group by 1
            ),
            missing_tables as (
                select
                    "create or replace table `"
                    || table_name
                    || "` as select * from  `{{target.database}}.{{target.schema}}.holoway_sessions` where session_date = '"
                    || parse_date("%Y%m%d", table_date)
                    || "'" as view_query
                from holoway_session_dates as src
                left join existing_tables as dest using (table_date)
                where
                    dest.table_date is null
                    or abs(
                        ifnull(
                            safe_divide(
                                src.session_count - dest.session_count,
                                src.session_count
                            ),
                            1
                        )
                    )
                    > 0.01
            )

        select view_query
        from missing_tables
    )
do
  execute immediate view_query.view_query;
    end for
    ;
{% endmacro %}

