macro.product.bq_user_ids.macro_sql:
{% macro bq_user_ids() %}
    {% if (var("identifiers").get("tables", []) | length) > 0 %}

        -- === Связные компоненты через итеративную пропагацию меток ===
DECLARE changed INT64 DEFAULT 1;
DECLARE iter INT64 DEFAULT 0;
DECLARE max_iter INT64 DEFAULT 500;  -- защитный лимит

        -- 1) Соберём неориентированный граф без дубликатов направлений
CREATE TEMP TABLE undirected AS
SELECT DISTINCT src, dst FROM (
  SELECT x AS src, y AS dst FROM {{ ref("int__user_ids_encoded") }}
  UNION ALL
  SELECT y AS src, x AS dst FROM {{ ref("int__user_ids_encoded") }});

        -- 2) Полный список вершин
CREATE TEMP TABLE nodes AS
SELECT DISTINCT node FROM (
  SELECT src AS node FROM undirected
  UNION ALL
  SELECT dst AS node FROM undirected
);

        -- 3) Текущие метки: первоначально метка вершины = её id
CREATE TEMP TABLE labels AS
SELECT node, node AS label FROM nodes;

        -- 4) Итеративно улучшаем метки: u.dst получает минимум из своих соседей u.src
        LOOP
        set iter = iter + 1
        ;

        -- min-метка среди соседей (для каждого dst)
  CREATE TEMP TABLE neighbor_min AS
  SELECT u.dst AS node, MIN(l.label) AS min_neighbor_label
  FROM undirected u
  JOIN labels     l ON l.node = u.src
  GROUP BY node;

        -- кандидаты на улучшение
  CREATE TEMP TABLE changes AS
  SELECT l.node, LEAST(l.label, IFNULL(n.min_neighbor_label, l.label)) AS new_label
  FROM labels l
  LEFT JOIN neighbor_min n USING (node)
  WHERE LEAST(l.label, IFNULL(n.min_neighbor_label, l.label)) < l.label;

        set changed = (SELECT COUNT(*) FROM changes)
        ;

        -- применяем улучшения
  UPDATE labels t
  SET label = c.new_label
  FROM changes c
  WHERE t.node = c.node;

  DROP TABLE neighbor_min;
  DROP TABLE changes;

        IF changed = 0 or iter >= max_iter
        then LEAVE
        ;
        END IF
        ;
        END LOOP
        ;

        -- 5) Группируем вершины по меткам-компонентам
CREATE OR REPLACE TABLE `{{ target.schema }}.int__user_ids_connected` AS
SELECT ARRAY_AGG(node) AS ids
FROM labels
GROUP BY label

    {% endif %}
{% endmacro %}

macro.product.attribution_events.macro_sql:
{% macro attribution_events(name) %}

    -- Проверяем, что имя модели соответствует ожидаемому имени "int__xxx_events"
    {% if this.table != "int__" + name + "_events" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be int__"
                ~ name
                ~ "_events"
            )
        }}
    {% endif %}

    {% set user_ids_ref = ref("int__user_ids") %}

    -- Получаем глубину расчета атрибуции для продукта
    {% set calc_depth = (
        var("product")["attribution"].get(name, {}).get("calc_depth", 0)
    ) %}

    -- Определяем интервал обработки данных на основе глубины расчета атрибуции
    {% set processing_interval = product.get_processing_interval(
        "event_date", calc_depth
    ) %}

    -- Получаем глубину атрибуции (по умолчанию 30 дней)
    {% set attribution_depth = (
        var("product")["attribution"].get(name, {}).get("depth", 30)
    ) %}

    -- Получаем список таблиц с событиями, связанных с атрибуцией для продукта
    {% set events_tables = (
        var("product")["attribution"].get(name, {}).get("events", [])
    ) %}

    -- Создаем пустой список для хранения связей с таблицами
    {% set relations = [] %}

    -- Добавляем ссылки на таблицы событий в список, если они заданы
    {% for table_name in events_tables %}
        {% if not table_name.startswith(
            ("stg__", "int__")
        ) or not table_name.endswith("_events") %}
            {{
                exceptions.raise_compiler_error(
                    "Invalid model name. Got: "
                    ~ table_name
                    ~ ". Should be int__table_name_events"
                )
            }}
        {% endif %}
        {{ relations.append(ref(table_name)) or "" }}
    {% else %}
        -- Если таблицы событий не заданы, используем таблицу по умолчанию
        -- "int__metrika_events"
        {{ relations.append(ref("int__metrika_events")) or "" }}
    {% endfor %}

    -- Определяем условия пропуска, если они заданы
    {% set skip_condition = (
        var("product")["attribution"].get(name, {}).get("skip_condition", [])
    ) %}
    {% set skip_stick_condition = (
        var("product")["attribution"]
        .get(name, {})
        .get("skip_stick_condition", [])
    ) %}

    with
        selected as (
            -- Формируем SELECT запрос для выборки данных о событиях
            select
                event_source,
                event_time,
                event_date,
                event_id,
                {{ product.get_operator("lagInFrame", "event_id") }} over (
                    partition by
                        if(coalesce(uids.user_id, '') = '', ev.user_id, uids.user_id)
                    order by event_time
                ) as previous_event_id,
                -- Заменяем user_id на идентификатор из таблицы uids, если такой
                -- существует
                if(
                    coalesce(uids.user_id, '') = '', ev.user_id, uids.user_id
                ) as user_id,
                {{ product.basic_columns() }},
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    {{ dimension["name"] }},
                {% endfor %}
                event_cost
            from
                (
                    {{ product.union_relations(relations, source_column_name=None) }}
                ) as ev  -- Объединяем все таблицы событий
            -- Если есть таблицы с идентификаторами, выполняем левое соединение с
            -- таблицей
            -- int__user_ids
            left join {{ user_ids_ref }} as uids on ev.user_id = uids.id
            where
                -- Фильтруем события по дате: события должны быть в пределах заданного
                -- интервала
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    event_date
                    between '{{ processing_interval["from"] }}'
                    -- - interval {{ attribution_depth }} day
                    and '{{ processing_interval["to"] }}'
                {% endif %}
        ),
        user_ids_with_transactions as (
            select
                -- Заменяем user_id на идентификатор из таблицы uids, если такой
                -- существует
                if(
                    coalesce(uids.user_id, '') = '', uid.user_id, uids.user_id
                ) as user_id
            from {{ ref("int__" + name + "_transactions_user_ids") }} as uid
            -- Если есть таблицы с идентификаторами, выполняем левое соединение с
            -- таблицей
            -- int__user_ids
            left join {{ user_ids_ref }} as uids on uid.user_id = uids.id
        ),

        marked_for_attribution as (
            select distinct
                current_event.* except (previous_event_id),
                {% if adapter.type() == "clickhouse" -%}
                    multiIf(
                        false,
                        0,
                        {% for condition in skip_condition -%}
                            {{ condition }}, {{ loop.index }},
                        {% endfor %}
                        {%- for condition in skip_stick_condition -%}
                            (
                                1 = 1
                                {% for field, value in condition.current -%}
                                    and current_event.{{ field }} = '{{ value }}'
                                {% endfor %}
                                {%- for field, value in condition.previous -%}
                                    and previous_event.{{ field }} = '{{ value }}'
                                {% endfor %}
                                and dateDiff(
                                    'minute',
                                    previous_event.event_time,
                                    current_event.event_time
                                )
                                <= {{ condition.window }}
                            ),
                            {{ loop.index + skip_condition | length }},
                        {% endfor %}
                        0
                    ) as skip_condition_rank
                {%- elif adapter.type() == "bigquery" %}
                    {% if skip_condition or skip_stick_condition %}
                        case
                            {% for condition in skip_condition %}
                                when {{ condition }} then {{ loop.index }}
                            {% endfor %}

                            {%- for condition in skip_stick_condition %}
                                when
                                    (
                                        1 = 1
                                        {% for field, value in condition.current %}
                                            and current_event.{{ field }}
                                            = '{{ value }}'
                                        {% endfor %}
                                        {% for field, value in condition.previous %}
                                            and previous_event.{{ field }}
                                            = '{{ value }}'
                                        {% endfor %}
                                        and timestamp_diff(
                                            current_event.event_time,
                                            previous_event.event_time,
                                            minute
                                        )
                                        <= {{ condition.window }}
                                    )
                                then {{ loop.index + skip_condition | length }}
                            {% endfor %}
                            else 0
                        end as skip_condition_rank
                    {% else %} 0 as skip_condition_rank
                    {% endif %}
                {%- endif %}

            from
                (
                    select
                        selected.*,
                        coalesce(ids.user_id, '') <> '' as is_attribution_event
                    from selected
                    left join
                        user_ids_with_transactions as ids
                        on selected.user_id = ids.user_id
                ) current_event
            left join
                selected as previous_event
                on previous_event.event_id = current_event.previous_event_id
            where
                current_event.event_id <> coalesce(current_event.previous_event_id, '')
        ),
        optimized as (
            select
                {% if adapter.type() == "clickhouse" -%}
                    * replace (
                        toLowCardinality(utm_source) as utm_source,
                        toLowCardinality(utm_campaign) as utm_campaign,
                        toLowCardinality(utm_medium) as utm_medium,
                        toLowCardinality(utm_term) as utm_term,
                        toLowCardinality(utm_content) as utm_content,
                        toLowCardinality(campaign_id) as campaign_id
                    )
                {%- elif adapter.type() == "bigquery" %} *
                {% endif %}
            from marked_for_attribution as s
        )
    select *
    from optimized
{% endmacro %}

macro.product.classic_report.macro_sql:
{% macro classic_report(name) %}

    -- Проверяем, что имя модели соответствует ожидаемому имени "_report"
    {% if this.table != name + "_report" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be"
                ~ name
                ~ "_report"
            )
        }}
    {% endif %}
    {% set attrib = var("product").get("attribution", {}).get(name, {}) %}

    -- Получаем глубину расчета атрибуции для продукта
    {% set calc_depth = attrib.get("calc_depth", 0) %}

    -- Определяем глубину атрибуции (по умолчанию 30 дней)
    {% set attribution_depth = attrib.get("depth", 30) %}

    {% set processing_interval = product.get_processing_interval(
        "event_date", min_processing_interval=calc_depth
    ) %}

    -- Определяем типы атрибуции (последний клик, первый клик и линейный)
    {% set attribution_types = ["lc", "ln", "fc"] %}

    -- Получаем таблицы транзакций для продукта
    {% set transaction_tables = attrib.get("transactions", {}) %}

    -- Подсчитываем количество дополнительных измерений для атрибуции
    {% set dimension_count = (
        var("product").get("events", {}).get("extra_dimensions", []) | length
    ) %}

    {% set event_dimensions = [] %}
    {% for dim in var("product").get("events", {}).get("extra_dimensions", []) %}
        {{ event_dimensions.append("event." + dim["name"]) or "" }}
    {% endfor %}

    -- Определяем метрики и измерения транзакций
    {% set transaction_metrics = [] %}
    {% set transaction_dimensions = [] %}
    {% for table_name, part in transaction_tables.items() %}
        -- Собираем метрики транзакций
        {% for metric in part.get("metrics", []) %}
            {{ transaction_metrics.append(metric) or "" }}
        {% endfor %}
        -- Собираем измерения транзакций
        {% for dimension in part.get("dimensions", []) %}
            {{ transaction_dimensions.append(dimension) or "" }}
        {% endfor %}
    {% endfor %}

    {% set cohort_dimensions = [] %}
    {% set cohort_dimension_names = [] %}
    {% if attrib["cohorts"] %}

        {% set cohort_dimensions = [
            ("c.cohort_day", "cohort_day"),
            ("toStartOfWeek(c.cohort_day)", "cohort_week"),
            ("toStartOfMonth(c.cohort_day)", "cohort_month"),
            ("c.cohort_event_source", "cohort_event_source"),
            ("c.cohort_utm_source", "cohort_utm_source"),
            ("c.cohort_utm_campaign", "cohort_utm_campaign"),
            ("c.cohort_utm_medium", "cohort_utm_medium"),
            ("c.cohort_utm_term", "cohort_utm_term"),
            ("c.cohort_utm_content", "cohort_utm_content"),
        ] %}
        {% set cohort_dimension_names = [
            "cohort_day",
            "cohort_week",
            "cohort_month",
            "cohort_event_source",
            "cohort_utm_source",
            "cohort_utm_campaign",
            "cohort_utm_medium",
            "cohort_utm_term",
            "cohort_utm_content",
        ] %}
    {% endif %}
    {% set cohort_dimensions_count = cohort_dimensions | length %}
    -- Обновляем общее количество измерений, включая уникальные транзакционные измерения
    {% set dimension_count = (
        var("product").get("events", {}).get("extra_dimensions", []) | length
    ) + (transaction_dimensions | unique | list | length) %}

    -- Загружаем справочники
    {% set maps = attrib.get("maps", []) %}
    {% for map in maps %}
        {% if not map["name"].endswith("_map") %}
            {{
                exceptions.raise_compiler_error(
                    "Invalid map name. Got: "
                    ~ map["name"]
                    ~ ". Should be int__map_name_map"
                )
            }}
        {% endif %}
    {% endfor %}

    with
        -- Создаем фиктивные события для транзакций
        fake_transaction_events as (
            select distinct
                'fake_transaction_events' as event_source,
                transaction_time as event_time,
                {{ product.get_operator("toDate", "transaction_time") }} as event_date,
                event_id,
                {% if (
                    var("product").get("identifiers", {}).get("tables", [])
                    | length
                ) > 0 %}
                    if(
                        coalesce(uids.user_id, '') != '', uids.user_id, ev.user_id
                    ) as user_id,
                {% else %} user_id,
                {% endif %}
                {{ product.basic_columns() }},
                -- Добавляем дополнительные измерения атрибуции
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    '' as {{ dimension["name"] }},
                {% endfor %}
                0.0 as event_cost
            from {{ ref("int__" + name + "_value_attribution") }} as ev
            {% if (
                    var("product").get("identifiers", {}).get("tables", [])
                    | length
                ) > 0 %}
                left join {{ ref("int__user_ids") }} as uids on ev.user_id = uids.id
            {% endif %}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    {{ product.get_operator("toDate", "transaction_time") }}
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
                and is_transaction_event
                and utm_source != ''
                and utm_medium != ''
        ),
        -- Создаем фиктивные события для затрат
        fake_cost_events as (
            select distinct
                'fake_cost_events' as event_source,
                {{ product.get_operator("toDateTime", "cost_date") }} as event_time,
                cost_date as event_date,
                'unattributed_' || cost_id as event_id,
                'unattributed_' || cost_id as user_id,
                {{ product.basic_columns() }},
                -- Добавляем дополнительные измерения атрибуции
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    '' as {{ dimension["name"] }},
                {% endfor %}
                0.0 as event_cost
            from {{ ref("int__" + name + "_cost_attribution_non_attributed") }}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    cost_date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                    and utm_source != ''
                    and utm_medium != ''
                {% endif %}

        ),
        -- Объединяем все события: реальные, транзакционные и затраты
        events as (
            select
                event_source,
                event_time,
                event_date,
                event_id,
                user_id,
                {{ product.basic_columns() }},
                -- Добавляем дополнительные измерения атрибуции
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    {{ dimension["name"] }},
                {% endfor %}
                event_cost
            from {{ ref("int__" + name + "_events") }}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    event_date
                    {% if adapter.type() == "clickhouse" %}
                        between toDate('{{ processing_interval["from"] }}')
                        - interval {{ attribution_depth }} day
                    {% elif adapter.type() == "bigquery" %}
                        between DATE_SUB(
                            DATE('{{ processing_interval["from"] }}'),
                            interval {{ attribution_depth }} DAY
                        )
                    {% endif %}
                    and '{{ processing_interval["to"] }}'
                    and utm_source != ''
                    and utm_medium != ''
                {% endif %}

            union all

            select *
            from fake_cost_events
        ),
        -- Извлекаем данные по атрибуции затрат
        cost_attribution as (
            select *
            from {{ ref("int__" + name + "_cost_attribution") }}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    attributed_cost_date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
        ),

        events_with_cost as (
            select
                e.event_date as event_date,
                e.event_source as event_source,
                {{ product.basic_columns(alias="e") }},
                {% for field_value, field_name in cohort_dimensions %}
                    {{ field_value }} as {{ field_name }},
                {% endfor %}
                -- Добавляем дополнительные измерения атрибуции
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    e.{{ dimension["name"] }} as {{ dimension["name"] }},
                {% endfor %}
                -- Добавляем транзакционные измерения
                '' as transaction_name,
                '' as transaction_source,

                {% for dimension in transaction_dimensions | unique %}
                    '' as {{ dimension }},
                {% endfor %}

                coalesce(count(distinct e.event_id), 0) as events,
                coalesce(sum(ca.attributed_impressions), 0.0) as impressions,
                coalesce(sum(ca.attributed_clicks), 0.0) as clicks,
                coalesce(sum(ca.attributed_cost), 0.0)
                + coalesce(sum(e.event_cost), 0.0) as cost,

                -- Считаем метрики по типам атрибуции
                {% for metric in transaction_metrics | unique %}
                    {% for attr in attribution_types %}
                        0.0 as {{ metric }}_{{ attr }},
                    {% endfor %}
                {% endfor %}
                -- Считаем общие значения по типам атрибуции
                {% for attr in attribution_types %}
                    0.0 as value_{{ attr }} {% if not loop.last %},{% endif %}
                {% endfor %}

            from events as e
            left join cost_attribution ca on e.event_id = ca.event_id
            {% if cohort_dimensions_count > 0 %}
                left join
                    {{ ref("int__" + name + "_user_cohorts") }} as c
                    on e.user_id = c.user_id
            {% endif %}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    e.event_date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
                {{
                    dbt_utils.group_by(
                        4 + var("product").get("basic_columns")
                        | length + dimension_count + cohort_dimensions_count
                    )
                }}
        ),
        value_events as (
            select *
            from events
            union all

            select *
            from fake_transaction_events

        ),
        -- Извлекаем данные по атрибуции стоимости
        value_attribution as (
            select *
            from {{ ref("int__" + name + "_value_attribution") }}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    {{ product.get_operator("toDate", "transaction_time") }}
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
        ),

        values_with_events as (

            select
                {{ product.get_operator("toDate", "v.transaction_time") }}
                as event_date,
                e.event_source as event_source,
                {{ product.basic_columns(alias="e") }},
                {% for field_value, field_name in cohort_dimensions %}
                    {{ field_value }} as {{ field_name }},
                {% endfor %}
                -- Добавляем дополнительные измерения атрибуции
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    e.{{ dimension["name"] }} as {{ dimension["name"] }},
                {% endfor %}
                -- Добавляем транзакционные измерения
                v.transaction_name as transaction_name,
                v.transaction_source as transaction_source,
                {% for dimension in transaction_dimensions | unique %}
                    {{ product.get_operator("toString", "t." ~ dimension) }}
                    as {{ dimension }},
                {% endfor %}

                0 as events,
                0.0 as impressions,
                0.0 as clicks,
                0.0 as cost,
                -- Считаем метрики по типам атрибуции
                {% for metric in transaction_metrics | unique %}
                    {% for attr in attribution_types %}
                        {{
                            product.get_operator(
                                "toFloat",
                                "(sum(v.value_" ~ attr ~ " * t." ~ metric ~ "))",
                            )
                        }} as {{ metric }}_{{ attr }},
                    {% endfor %}
                {% endfor %}
                -- Считаем общие значения по типам атрибуции
                {% for attr in attribution_types %}
                    {{
                        product.get_operator(
                            "toFloat", "(sum(v.value_" ~ attr ~ "))"
                        )
                    }} as value_{{ attr }} {% if not loop.last %},{% endif %}
                {% endfor %}

            from value_attribution as v
            left join value_events as e on v.event_id = e.event_id
            left join
                {{ ref("int__" + name + "_transactions") }} as t
                on v.transaction_id = t.transaction_id
            {% if cohort_dimensions_count > 0 %}
                left join
                    {{ ref("int__" + name + "_user_cohorts") }} as c
                    on v.user_id = c.user_id
            {% endif %}
                {{
                    dbt_utils.group_by(
                        4 + var("product").get("basic_columns")
                        | length + dimension_count + cohort_dimensions_count
                    )
                }}
        ),
        all_events as (

            select *
            from events_with_cost
            union all
            select *
            from values_with_events
        ),

        -- Формируем финальный отчет
        enumerated_result as (
            select
                -- Генерируем уникальный идентификатор строки отчета
                {{
                    dbt_utils.generate_surrogate_key(
                        [
                            "event.event_date",
                            "event.event_source",
                            "event.transaction_name",
                            "event.transaction_source",
                            "event.utm_source",
                            "event.utm_medium",
                            "event.utm_campaign",
                            "event.utm_term",
                            "event.utm_content",
                        ]
                        + cohort_dimension_names
                        + transaction_dimensions
                        | unique
                        | list + event_dimensions
                        | unique
                        | list,
                    )
                }} as row_id, *
            from all_events as event
        ),

        {% for m in maps %}
            {{ m["name"] }}_unique as (
                select *
                from {{ ref(m["name"]) }} as map_{{ m["name"] }}
                qualify
                    row_number() over (
                        partition by
                            {% for k in m["keys"] %}
                                map_{{ m["name"] }}.{{ k }}
                                {% if not loop.last %}, {% endif %}
                            {% endfor %}
                    )
                    = 1
            ),
        {% endfor %}
        result as (
            select
                e.row_id,
                e.event_date as event_date,
                e.event_source as event_source,
                {{ product.basic_columns(alias="e", is_low_cardinality=True) }},
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    e.{{ dimension["name"] }} as {{ dimension["name"] }},
                {% endfor %}
                -- Добавляем имзмерения из справочников
                {% for m in maps %}
                    {% for v in m["values"] %}
                        map_{{ m["name"] }}.{{ v }} as {{ v }},
                    {% endfor %}
                {% endfor %}
                e.transaction_name as transaction_name,
                e.transaction_source as transaction_source,
                {% for _, field_name in cohort_dimensions %}
                    e.{{ field_name }} as {{ field_name }},
                {% endfor %}
                {% for dimension in transaction_dimensions | unique %}
                    e.{{ dimension }} as {{ dimension }},
                {% endfor %}

                e.events as events,
                e.impressions as impressions,
                e.clicks as clicks,
                e.cost as cost,
                -- Считаем метрики по типам атрибуции
                {% for metric in transaction_metrics | unique %}
                    {% for attr in attribution_types %}
                        e.{{ metric }}_{{ attr }} as {{ metric }}_{{ attr }},
                    {% endfor %}
                {% endfor %}
                -- Считаем общие значения по типам атрибуции
                {% for attr in attribution_types %}
                    e.value_{{ attr }} as value_{{ attr }}
                    {% if not loop.last %},{% endif %}
                {% endfor %}

            from enumerated_result as e

            {% for m in maps %}
                left join
                    {{ m["name"] }}_unique as map_{{ m["name"] }}
                    on {% for k in m["keys"] %}
                        e.{{ k }} = map_{{ m["name"] }}.{{ k }}
                        {% if not loop.last %} and {% endif %}
                    {% endfor %}
            {% endfor %}

        )

    -- Итоговый запрос: выбираем все данные из результата
    select *
    from result

{% endmacro %}

macro.product.basic_columns.macro_sql:
{% macro basic_columns(is_empty=False, is_low_cardinality=False, alias=None) %}
    {% if adapter.type() == "bigquery" %}
        {% set is_low_cardinality = False %}
    {% endif %}
    {% for col in var("product").get("basic_columns") -%}
        {% if is_empty %}
            {% if is_low_cardinality %} toLowCardinality('')
            {% else %} ''
            {% endif %} as {{ col }}
        {% else %}
            {% if is_low_cardinality %}
                toLowCardinality({% if alias %}{{ alias -}}.{%- endif -%}{{ col }}) as
            {% else %} {% if alias %} {{ alias -}}.{%- endif -%}
            {% endif %}{{ col }}
        {% endif %}
        {%- if not loop.last %}, {% endif %}
    {% endfor %}
{% endmacro %}

macro.product.attribution_transactions.macro_sql:
{% macro attribution_transactions(name) %}

    -- Проверяем, что имя модели соответствует ожидаемому имени "int__xxx_transactions"
    {% if this.table != "int__" + name + "_transactions" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be int__"
                ~ name
                ~ "_transactions"
            )
        }}
    {% endif %}

    -- Получаем список таблиц с транзакциями, связанных с атрибуцией для продукта
    {% set transaction_tables = (
        var("product")["attribution"].get(name, {}).get("transactions", {})
    ) %}

    -- Получаем глубину расчета атрибуции для продукта
    {% set calc_depth = (
        var("product")["attribution"].get(name, {}).get("calc_depth", 0)
    ) %}
    {% set transaction_calc_depth = (
        var("product")["attribution"]
        .get(name, {})
        .get("transaction_calc_depth", 0)
    ) %}
    {% if transaction_calc_depth > 0 %}
        {% set calc_depth = transaction_calc_depth %}
    {% endif %}

    -- Определяем интервал обработки данных на основе глубины расчета атрибуции
    {% set processing_interval = product.get_processing_interval(
        "transaction_time", calc_depth
    ) %}

    -- Создаем пустой список для хранения ссылок на таблицы транзакций
    {% set relations = [] %}

    -- Добавляем ссылки на таблицы транзакций в список
    {% for table_name, _ in transaction_tables.items() %}
        {% if not table_name.startswith(
            ("int__", "stg__")
        ) or not table_name.endswith("_transactions") %}
            {{
                exceptions.raise_compiler_error(
                    "Invalid model name. Got: "
                    ~ table_name
                    ~ ". Should be int__table_name_transactions"
                )
            }}
        {% endif %}
        {{ relations.append(ref(table_name)) or "" }}
    {% endfor %}

    -- Формируем SELECT запрос для выборки данных о транзакциях
    select
        ts.*  -- Выбираем все колонки из объединенной таблицы транзакций
        {% if (var("product").get("identifiers", {}).get("tables", []) | length) > 0 %}
            -- Заменяем user_id на идентификатор из таблицы uids, если такой существует
            replace (if(coalesce(uids.user_id, '') = '', ts.user_id, uids.user_id) as user_id)
        {% endif %}
    from
        (
            {{ product.union_relations(relations, source_column_name=None) }}  -- Объединяем все таблицы транзакций без указания столбца источника
        ) as ts

    {% if (var("product").get("identifiers", {}).get("tables", []) | length) > 0 %}
        -- Если есть таблицы с идентификаторами, выполняем левое соединение с таблицей
        -- int__user_ids
        left join {{ ref("int__user_ids") }} as uids on ts.user_id = uids.id
    {% endif %}

    -- Фильтруем транзакции по времени: транзакции должны быть в пределах заданного
    -- интервала
    where
        {% if processing_interval["is_updated"] %} false
        {% else %}
            {% if adapter.type() == "clickhouse" %} toDate(transaction_time)
            {% elif adapter.type() == "bigquery" %} date(transaction_time)
            {% endif %}
            between '{{ processing_interval["from"] }}'
            and '{{ processing_interval["to"] }}'
        {% endif %}
{% endmacro %}

macro.product.attribution_transactions_u.macro_sql:
{% macro attribution_transactions_user_ids(name) %}

    {% if this.table != "int__" + name + "_transactions_user_ids" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be int__"
                ~ name
                ~ "_transactions_user_ids"
            )
        }}
    {% endif %}
    select distinct user_id
    from {{ ref("int__" + name + "_transactions") }}
{% endmacro %}

macro.product.value_attribution.macro_sql:
{% macro value_attribution(name) %}

    -- Проверяем, что имя модели соответствует ожидаемому имени
    -- "int___value_attribution"
    {% if this.table != "int__" + name + "_value_attribution" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be int__"
                ~ name
                ~ "_value_attribution"
            )
        }}
    {% endif %}

    -- Определяем глубину атрибуции (по умолчанию 30 дней)
    {% set attribution_depth = (
        var("product")["attribution"].get(name, {}).get("depth", 30)
    ) %}

    -- Устанавливаем глубину расчета атрибуции
    {% set calc_depth = (
        var("product")["attribution"].get(name, {}).get("calc_depth", 0)
    ) %}

    {% set value_attribution_calc_depth = (
        var("product")["attribution"]
        .get(name, {})
        .get("transaction_calc_depth", 0)
    ) %}
    {% if value_attribution_calc_depth > 0 %}
        {% set calc_depth = value_attribution_calc_depth %}
    {% endif %}
    -- Получаем интервал обработки данных по дате события
    {% set processing_interval = product.get_processing_interval(
        "event_date", calc_depth
    ) %}

    -- Если макрос выполняется, выводим информацию в лог
    {% if execute %}
        {{
            log(
                "Attributing value to events. Attribution window: "
                ~ attribution_depth,
                true,
            )
        }}
    {% endif %}

    with
        filtered_events as (
            select
                event_id,
                event_date,
                event_source,
                {{ product.basic_columns() }},
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    {{ dimension["name"] }},
                {% endfor %}
                event_time,
                skip_condition_rank,
                {% if (
                    var("product").get("identifiers", {}).get("tables", [])
                    | length
                ) > 0 %}
                    if(coalesce(uids.user_id, '') = '', event.user_id, uids.user_id) as user_id
                {% else %} user_id
                {% endif %}
            from {{ ref("int__" + name + "_events") }} as event
            {% if (
                    var("product").get("identifiers", {}).get("tables", [])
                    | length
                ) > 0 %}
                -- Если есть таблицы с идентификаторами, выполняем левое соединение с
                -- таблицей
                -- int__user_ids
                left join {{ ref("int__user_ids") }} as uids on event.user_id = uids.id
            {% endif %}
            where
                event.event_date
                between '{{ processing_interval["from"] }}'
                - interval {{ attribution_depth }} day
                and '{{ processing_interval["to"] }}'
                and utm_source != ''
                and utm_medium != ''
        ),
        filtered_transactions as (
            select
                transaction_id,
                transaction_time,
                transaction_name,
                transaction_source,
                {% if (
                    var("product").get("identifiers", {}).get("tables", [])
                    | length
                ) > 0 %}
                    if(coalesce(uids.user_id, '') = '', transaction.user_id, uids.user_id) as user_id
                {% else %} user_id
                {% endif %}
            from {{ ref("int__" + name + "_transactions") }} as transaction
            {% if (
                    var("product").get("identifiers", {}).get("tables", [])
                    | length
                ) > 0 %}
                -- Если есть таблицы с идентификаторами, выполняем левое соединение с
                -- таблицей
                -- int__user_ids
                left join
                    {{ ref("int__user_ids") }} as uids on transaction.user_id = uids.id
            {% endif %}
            where
                {{ product.to_date("transaction.transaction_time") }}
                between '{{ processing_interval["from"] }}'
                and '{{ processing_interval["to"] }}'

        ),
        -- Выбираем транзакции и связываем их с событиями
        events_with_transactions as (
            select
                transaction.transaction_id,
                transaction.transaction_time as transaction_time,
                transaction.transaction_name as transaction_name,
                transaction.transaction_source as transaction_source,
                transaction.user_id as user_id,
                if(
                    event.event_id != '',
                    event.event_id,
                    'transaction_event_' || transaction.transaction_id
                ) as event_id,
                if(
                    event.event_id != '', event.event_time, transaction.transaction_time
                ) as event_time,
                if(
                    event.event_id != '',
                    event.event_date,
                    {{ product.to_date("transaction.transaction_time") }}
                ) as event_date,
                if(
                    event.event_id != '',
                    event.event_source,
                    transaction.transaction_source
                ) as event_source,
                if(
                    event.event_id != '', event.utm_source, transaction.transaction_name
                ) as utm_source,
                if(
                    event.event_id != '',
                    event.utm_medium,
                    transaction.transaction_source
                ) as utm_medium,
                event.utm_campaign as utm_campaign,
                event.utm_content as utm_content,
                event.utm_term as utm_term,
                -- Добавляем дополнительные измерения
                {% for dimension in var("product").get("events", {}).get(
                    "extra_dimensions", []
                ) %}
                    {{ dimension["name"] }},
                {% endfor %}
                -- Нумеруем события по порядку для каждой транзакции
                row_number() over (
                    partition by transaction.user_id, transaction.transaction_id
                    order by event.event_time
                ) as event_number,
                skip_condition_rank,
                coalesce(event.event_id, '') = '' as is_transaction_event  -- Проверяем, если событие связано с транзакцией
            from filtered_transactions as transaction
            left join
                filtered_events as event
                on event.user_id = transaction.user_id
                and event.event_time
                between transaction.transaction_time
                - interval {{ attribution_depth }} day and transaction.transaction_time
        ),

        -- Определяем условия пропуска, если они заданы
        {% set skip_transaction = (
            var("product")["attribution"]
            .get(name, {})
            .get("skip_transactions", True)
        ) %}

        -- Если есть условия пропуска, присваиваем им ранги
        {% if adapter.type() == "clickhouse" %}
            ranked_by_skip_conditions as (
                select
                    *,
                    multiIf(
                        {% if skip_transaction %}is_transaction_event, 999, {% endif %}
                        false,  -- Сделано для того, чтобы не ломался multiIf если мы пропускаем тразакции
                        -1,
                        skip_condition_rank
                    ) as condition_rank
                from events_with_transactions
            ),
            rank_stats as (
                select transaction_id, user_id, min(condition_rank) as min_rank
                from ranked_by_skip_conditions
                group by 1, 2
            ),
        {% elif adapter.type() == "bigquery" %}
            ranked_by_skip_conditions as (
                select
                    *,
                    case
                        when is_transaction_event
                        then 999
                        when false
                        then -1
                        else skip_condition_rank
                    end as condition_rank
                from events_with_transactions
            ),
            ranked_by_transaction_user as (
                select
                    transaction_id,
                    user_id,
                    event_id,
                    condition_rank,
                    ROW_NUMBER() over (
                        partition by transaction_id, user_id order by condition_rank ASC
                    ) as rn
                from ranked_by_skip_conditions
            ),
            rank_stats as (
                select transaction_id, user_id, condition_rank as min_rank
                from ranked_by_transaction_user
                where rn = 1
            ),
        {% endif %}

        -- Отмечаем события, которые будут учитываться для расчета атрибуции
        marked_to_count as (
            select
                ranked.* except (condition_rank, skip_condition_rank),
                ranked.condition_rank = 0
                or ranked.condition_rank = min_rank as is_counted
            from ranked_by_skip_conditions as ranked
            left join
                rank_stats as stats
                on ranked.user_id = stats.user_id
                and ranked.transaction_id = stats.transaction_id
        ),
        -- Рассчитываем атрибутированные значения для событий
        result as (
            select
                * except (event_number, is_counted),
                -- Расчет для атрибуции по первому клику (first click)
                if(
                    row_number() over (
                        partition by user_id, transaction_id
                        order by is_counted desc, event_number
                    )
                    = 1,
                    1,
                    0
                ) as value_fc,
                -- Расчет для атрибуции по последнему клику (last click)
                if(
                    row_number() over (
                        partition by user_id, transaction_id
                        order by is_counted desc, event_number desc
                    )
                    = 1,
                    1,
                    0
                ) as value_lc,
                -- Расчет для линейной атрибуции (linear)
                if(
                    is_counted,
                    1 / countIf(is_counted) over (partition by user_id, transaction_id),
                    0
                ) as value_ln

            from marked_to_count
        )

    -- Выбираем все рассчитанные значения
    select *
    from
        result
        {% if adapter.type() == "clickhouse" -%}
            settings join_algorithm = 'grace_hash',
            allow_experimental_join_condition = 1
        {% endif %}
{% endmacro %}

macro.product.daily_cost_attribution.macro_sql:
{% macro daily_cost_attribution(name) %}
    {%- set model_name = this.name -%}
    {# Проверяем, что имя корректное #}
    {%- if not model_name.startswith("int__" ~ name ~ "_") -%}
        {{
            exceptions.raise_compiler_error(
                "Имя модели должно начинаться с 'int__"
                ~ name
                ~ "_'. Получено: "
                ~ model_name
            )
        }}
    {%- endif -%}

    {%- if not model_name.endswith("_cost_attribution") -%}
        {{
            exceptions.raise_compiler_error(
                "Имя модели должно заканчиваться на '_cost_attribution'. Получено: "
                ~ model_name
            )
        }}
    {%- endif -%}
    {%- set without_prefix = model_name | replace("int__" ~ name ~ "_", "") -%}
    {%- set entity = without_prefix | replace("_cost_attribution", "") -%}

    {# Загружаем конфиг #}
    {%- set cfg = var("product") -%}
    {%- set cost_entity = cfg.cost.daily.get(entity) -%}
    {# Проверяем наличие ключа #}
    {%- if cost_entity is none -%}
        {{
            exceptions.raise_compiler_error(
                "Entity '"
                ~ entity
                ~ "' не найден в vars.product.cost_attribtution.daily"
            )
        }}
    {%- endif -%}

    {%- set calc_depth = var("product").get("cost", {}).get("depth", 7) -%}
    {%- set processing_interval = product.get_processing_interval(
        "attributed_cost_date", min_processing_interval=calc_depth
    ) -%}

    {%- set utm_keys = [] -%}
    {%- for sub in cost_entity.utm_keys -%}
        {%- for item in sub -%} {%- do utm_keys.append(item) -%} {%- endfor -%}
    {%- endfor -%}
    {%- set unique_utm_keys = utm_keys | unique | list -%}
    {%- set processed_utm_list = [] -%}
    with
        cost_data as (
            {%- for table in cost_entity.tables %}
                select
                    cost_id,
                    cost_date,
                    {% for k in unique_utm_keys -%} {{ k }}, {% endfor %}
                    clicks,
                    impressions,
                    cost
                from {{ ref(table) }}
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else -%}
                        cost_date
                        between '{{ processing_interval["from"] }}'
                        and '{{ processing_interval["to"] }}'
                    {% endif %}
                {% if not loop.last %}
                    union all
                {% endif %}
            {%- endfor %}
        ),
        events_data as (
            select
                {% if "event_id" not in unique_utm_keys -%}
                    e.event_id,
                {% endif %}
                {% for k in unique_utm_keys -%} {{ k }}, {% endfor %}
                e.event_date as cost_date
            from {{ ref("int__" + name + "_events") }} e
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    e.event_date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
                and {% for utm_list in cost_entity.utm_keys %}
                    (
                        {% for col in utm_list -%}
                            {{ col }} != '' {% if not loop.last %} and {% endif %}
                        {% endfor %}
                    )
                    {% if not loop.last %} or {% endif %}
                {% endfor %}
        ),
        {%- for utm_list in cost_entity.utm_keys %}
            {%- if processed_utm_list %}
                {{ entity }}__{{ utm_list | join("_") }}__used_cost_ids as (
                    {% for p_utm_list in processed_utm_list -%}
                        select
                            {% if adapter.type() == "bigquery" %} a.*,
                            {% elif adapter.type() == "clickhouse" %}
                                arrayJoin(cost_ids) as
                            {% endif %} cost_id
                        from {{ entity }}__{{ p_utm_list }}__attributed a
                        {% if adapter.type() == "bigquery" %}
                            left join unnest(a.cost_ids) as cost_id on true
                        {% endif %}
                        {% if not loop.last %}
                            union all
                        {% endif %}
                    {% endfor %}
                ),
            {% endif -%}
            {{ entity }}__{{ utm_list | join("_") }}__costs as (
                select
                    cost_date,
                    {% for col in utm_list -%} {{ col }}, {% endfor %}
                    {{ product.get_operator("groupArray") }} (cost_id) as cost_ids,
                    sum(cost) as cost,
                    sum(impressions) as impressions,
                    sum(clicks) as clicks
                from cost_data
                {% if processed_utm_list and adapter.type() == "clickhouse" %}
                    anti join
                        {{ entity }}__{{ utm_list | join("_") }}__used_cost_ids using (
                            cost_id
                        )
                {% endif %}
                where
                    true
                    {% for col in utm_list -%} and {{ col }}!= '' {% endfor %}
                    {% if processed_utm_list and adapter.type() == "bigquery" %}
                        and cost_id not in (
                            select cost_id
                            from {{ entity }}__{{ utm_list | join("_") }}__used_cost_ids
                        )
                    {% endif %}
                group by {% for col in utm_list -%} {{ col }}, {% endfor %} cost_date
            ),
            {{ entity }}__{{ utm_list | join("_") }}__events as (
                select
                    e.cost_date,
                    {% if "event_id" not in utm_list -%}
                        e.event_id,
                    {% endif %}
                    {% for col in utm_list -%}
                        {{ col }}{% if not loop.last %}, {% endif %}
                    {% endfor %}
                from events_data e
                where true {% for col in utm_list -%} and {{ col }} != '' {% endfor %}
            ),
            {{ entity }}__{{ utm_list | join("_") }}__events_count as (
                select
                    cost_date,
                    {% for col in utm_list -%} {{ col }}, {% endfor %}
                    count(event_id) as events_count
                from {{ entity }}__{{ utm_list | join("_") }}__events
                group by {% for col in utm_list -%} {{ col }}, {% endfor %} cost_date
            ),
            {{ entity }}__{{ utm_list | join("_") }}__attributed as (

                select
                    cm.cost_date as attributed_cost_date,
                    e.event_id as event_id,
                    {% if adapter.type() == "clickhouse" %}
                        arrayFlatten(arrayFlatten(groupArray(cm.cost_ids))) as cost_ids,
                    {% elif adapter.type() == "bigquery" %}
                        ARRAY_CONCAT_AGG(cm.cost_ids) as cost_ids,
                    {% endif %}
                    {{ product.get_operator("any", "cm.cost") }}
                    / sum(e_c.events_count) as attributed_cost,
                    {{ product.get_operator("any", "cm.impressions") }}
                    / sum(e_c.events_count) as attributed_impressions,
                    {{ product.get_operator("any", "cm.clicks") }}
                    / sum(e_c.events_count) as attributed_clicks
                from {{ entity }}__{{ utm_list | join("_") }}__costs as cm
                join
                    {{ entity }}__{{ utm_list | join("_") }}__events as e using (
                        cost_date,
                        {%- for col in utm_list -%}
                            {{ col }}{%- if not loop.last -%}, {%- endif -%}
                        {%- endfor -%}
                    )
                join
                    {{ entity }}__{{ utm_list | join("_") }}__events_count as e_c
                    using (
                        cost_date,
                        {%- for col in utm_list -%}
                            {{ col }}{%- if not loop.last -%}, {%- endif -%}
                        {%- endfor -%}
                    )
                group by cm.cost_date, e.event_id
            ),
            {%- do processed_utm_list.append(utm_list | join("_")) -%}
        {% endfor %}
        empty_days as (
            select
                date as attributed_cost_date,
                'cost_attribution_{{ entity }}_empty_' || date as event_id,
                {{ product.get_operator("[]") }} as cost_ids,
                0.0 as attributed_cost,
                0.0 as attributed_impressions,
                0.0 as attributed_clicks
            from
                (
                    {% if adapter.type() == "clickhouse" %}
                        select
                            toDate('{{ processing_interval["from"] }}') + number as date
                        from
                            numbers(
                                dateDiff(
                                    'day',
                                    toDate('{{ processing_interval["from"] }}'),
                                    toDate('{{ processing_interval["to"] }}')
                                )
                                + 1
                            )
                    {% elif adapter.type() == "bigquery" %}
                        select
                            DATE_ADD(
                                DATE '{{ processing_interval["from"] }}',
                                interval day_offset DAY
                            ) as date
                        from
                            UNNEST(
                                GENERATE_ARRAY(
                                    0,
                                    DATE_DIFF(
                                        DATE '{{ processing_interval["to"] }}',
                                        DATE '{{ processing_interval["from"] }}',
                                        DAY
                                    )
                                )
                            ) as day_offset
                    {% endif %}
                )
            {% if processing_interval["is_updated"] %} where false {% endif %}
        ),
        result as (
            {%- for utm_list in cost_entity.utm_keys %}
                select *
                from {{ entity }}__{{ utm_list | join("_") }}__attributed
                union all
            {% endfor %}
            select *
            from empty_days
        )
    select *
    from result
{% endmacro %}

macro.product.monthly_cost_attribution.macro_sql:
{% macro monthly_cost_attribution(name) %}
    {%- set model_name = this.name -%}
    {# Проверяем, что имя корректное #}
    {%- if not model_name == "int__" ~ name ~ "_monthly_cost_attribution" -%}
        {{
            exceptions.raise_compiler_error(
                "Имя модели должно быть 'int__"
                ~ name
                ~ "_monthly_cost_attribution'. Получено: "
                ~ model_name
            )
        }}
    {%- endif -%}
    {% set calc_depth = var("product").get("cost", {}).get("depth", 7) %}
    -- Получаем интервал обработки данных по столбцу "event_date"
    {% set processing_interval = product.get_processing_interval(
        "attributed_cost_date", min_processing_interval=calc_depth
    ) %}
    {%- set col_group_ref = ref("int__" ~ name ~ "_monthly_cost") -%}
    {%- call statement("column_groups", fetch_result=True) -%}
        with
            columns as (
                select distinct
                    {% for col in var("product").get("basic_columns") %}
                        if({{ col }} = '', '', '{{ col }}') as {{ col }}
                        {% if not loop.last %}, {% endif %}
                    {% endfor %}
                from {{ col_group_ref }}
                where
                    cost_date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                    and cost > 0

            ),
            result as (
                select
                    {% if adapter.type() == "clickhouse" %}
                        arrayStringConcat(
                            arrayFilter(
                                x -> notEmpty(x),
                                [
                                    utm_source,
                                    utm_medium,
                                    utm_campaign,
                                    utm_term,
                                    utm_content
                                ]
                            ),
                            ','
                        ) as column_group
                    {% elif adapter.type() == "bigquery" %}
                        ARRAY_TO_STRING(
                            ARRAY(
                                select x
                                from UNNEST([
                                    utm_source,
                                    utm_medium,
                                    utm_campaign,
                                    utm_term,
                                    utm_content
                                ]) as x
                                where x is not null and x != ''
                            ),
                            ','
                        ) as column_group
                    {% endif %}
                from columns
            )
        select *
        from result
    {%- endcall -%}
    {%- set column_groups = load_result("column_groups")["data"] -%}
    {% set all_columns = var("product").get("basic_columns") %}

    {%- set entity = "manual" -%}
    {%- set utm_keys = [] -%}
    {%- for sub in column_groups -%}
        {%- for item in sub[0].split(",") -%}
            {%- do utm_keys.append(item) -%}
        {%- endfor -%}
    {%- endfor -%}
    {%- set unique_utm_keys = utm_keys | unique | list -%}
    {%- set processed_utm_list = [] -%}
    {%- set events_ref = ref("int__" + name + "_events") -%}
    {%- set model_ref = ref("int__" + name + "_monthly_cost") -%}
    with
        {% if column_groups | length > 0 %}
            cost_data as (
                select
                    cost_id,
                    cost_date,
                    {% for k in unique_utm_keys -%} {{ k }}, {% endfor %}
                    clicks,
                    impressions,
                    cost
                from {{ model_ref }} e
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else -%}
                        cost_date
                        between '{{ processing_interval["from"] }}'
                        and '{{ processing_interval["to"] }}'
                    {% endif %}
            ),
            {%- for utm_list in column_groups %}
                events_data__{{ utm_list[0].split(",") | join("_") }} as (
                    select
                        e.event_date as cost_date,
                        {% for k in unique_utm_keys -%} {{ k }}, {% endfor %}
                        e.event_id
                    from {{ events_ref }} e
                    where
                        {% if processing_interval["is_updated"] %} false
                        {% else %}
                            e.event_date
                            between '{{ processing_interval["from"] }}'
                            and '{{ processing_interval["to"] }}'
                        {% endif %}
                        and {% for col in utm_list[0].split(",") -%}
                            {{ col }} != '' {% if not loop.last %} and {% endif %}
                        {% endfor %}
                ),
                {%- if processed_utm_list %}
                    {% set used_cost_ids = entity ~ '__' ~ utm_list[0].split(",") | join("_") ~ '__used_cost_ids' %}
                    {{ used_cost_ids }} as (
                        {% for p_utm_list in processed_utm_list -%}
                            select
                                {% if adapter.type() == "bigquery" %} a.*,
                                {% elif adapter.type() == "clickhouse" %}
                                    arrayJoin(cost_ids) as
                                {% endif %} cost_id
                            from {{ entity }}__{{ p_utm_list }}__attributed a
                            {% if adapter.type() == "bigquery" %}
                                left join unnest(a.cost_ids) as cost_id on true
                            {% endif %}
                            {% if not loop.last %}
                                union all
                            {% endif %}
                        {% endfor %}
                    ),
                {% endif -%}
                {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__costs as (
                    select
                        cost_date,
                        {% for col in utm_list[0].split(",") -%} {{ col }}, {% endfor %}
                        {{ product.get_operator("groupArray") }} (cost_id) as cost_ids,
                        sum(cost) as cost,
                        sum(impressions) as impressions,
                        sum(clicks) as clicks
                    from cost_data
                    {% if processed_utm_list and adapter.type() == "clickhouse" %}
                        anti join
                            {{ used_cost_ids }}
                            using (cost_id)
                    {% endif %}
                    where
                        true
                        {% for col in utm_list[0].split(",") -%}
                            and {{ col }}!= ''
                        {% endfor %}
                        {% if processed_utm_list and adapter.type() == "bigquery" %}
                            and cost_id not in (
                                select cost_id
                                from {{ used_cost_ids }}
                            )
                        {% endif %}
                    group by
                        {% for col in utm_list[0].split(",") -%}
                            {{ col }},
                        {% endfor %} cost_date
                ),
                {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__events as (
                    select
                        e.cost_date,
                        e.event_id,
                        {% for col in utm_list[0].split(",") -%}
                            {{ col }}{% if not loop.last %}, {% endif %}
                        {% endfor %}
                    from events_data__{{ utm_list[0].split(",") | join("_") }} e
                    where
                        true
                        {% for col in utm_list[0].split(",") -%}
                            and {{ col }} != ''
                        {% endfor %}
                ),
                {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__events_count
                as (
                    select
                        cost_date,
                        {% for col in utm_list -%} {{ col }}, {% endfor %}
                        count(event_id) as events_count
                    from {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__events
                    group by
                        {% for col in utm_list[0].split(",") -%}
                            {{ col }},
                        {% endfor %} cost_date
                ),
                {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__attributed as (

                    select
                        cm.cost_date as attributed_cost_date,
                        e.event_id,
                        {% if adapter.type() == "clickhouse" %}
                            arrayFlatten(
                                arrayFlatten(groupArray(cm.cost_ids))
                            ) as cost_ids,
                        {% elif adapter.type() == "bigquery" %}
                            ARRAY_CONCAT_AGG(cm.cost_ids) as cost_ids,
                        {% endif %}
                        {{ product.get_operator("any", "cm.cost") }}
                        / sum(e_c.events_count) as attributed_cost,
                        {{ product.get_operator("any", "cm.impressions") }}
                        / sum(e_c.events_count) as attributed_impressions,
                        {{ product.get_operator("any", "cm.clicks") }}
                        / sum(e_c.events_count) as attributed_clicks
                    from
                        {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__costs
                        as cm
                    join
                        {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__events
                        as e using (
                            cost_date,
                            {%- for col in utm_list[0].split(",") -%}
                                {{ col }}{%- if not loop.last -%}, {%- endif -%}
                            {%- endfor -%}
                        )
                    join
                        {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__events_count
                        as e_c using (
                            cost_date,
                            {%- for col in utm_list[0].split(",") -%}
                                {{ col }}{%- if not loop.last -%}, {%- endif -%}
                            {%- endfor -%}
                        )
                    group by cm.cost_date, e.event_id
                ),
                {%- do processed_utm_list.append(
                    utm_list[0].split(",") | join("_")
                ) -%}
            {% endfor %}
        {% endif %}
        empty_days as (
            select
                date_day as attributed_cost_date,
                'cost_attribution_{{ entity }}_empty_' || date_day as event_id,
                {{ product.get_operator("[]") }} as cost_ids,
                0.0 as attributed_cost,
                0.0 as attributed_impressions,
                0.0 as attributed_clicks
            from
                (
                    {% if adapter.type() == "clickhouse" %}
                        select
                            toDate('{{ processing_interval["from"] }}')
                            + number as date_day
                        from
                            numbers(
                                dateDiff(
                                    'day',
                                    toDate('{{ processing_interval["from"] }}'),
                                    toDate('{{ processing_interval["to"] }}')
                                )
                                + 1
                            )
                    {% elif adapter.type() == "bigquery" %}
                        select
                            DATE_ADD(
                                DATE '{{ processing_interval["from"] }}',
                                interval day_offset DAY
                            ) as date_day
                        from
                            UNNEST(
                                GENERATE_ARRAY(
                                    0,
                                    DATE_DIFF(
                                        DATE '{{ processing_interval["to"] }}',
                                        DATE '{{ processing_interval["from"] }}',
                                        DAY
                                    )
                                )
                            ) as day_offset
                    {% endif %}
                )
            {% if processing_interval["is_updated"] %} where false {% endif %}
        ),
        result as (
            {%- for utm_list in column_groups %}
                select *
                from {{ entity }}__{{ utm_list[0].split(",") | join("_") }}__attributed
                union all
            {% endfor %}
            select *
            from empty_days
        )
    select *
    from
        result
        {% if adapter.type() == "clickhouse" -%}
            settings join_algorithm = 'grace_hash'
        {% endif %}
{% endmacro %}

macro.product.check_costs.macro_sql:
{% macro check_costs(name) %}

    {% if this.table != "int__" + name + "_cost_check" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be int__"
                ~ name
                ~ "_cost_check"
            )
        }}
    {% endif %}

    {% set cost_groups = (
        var("product")["cost"].get("daily", {})
    ) %}

    with
        cost_base as (
            {% for cost_group, cost_info  in cost_groups.items() %}
                {% for cost_table in cost_info.get("tables", []) %}
                    select
                        cost_id,
                        cost_date,
                        '{{ cost_group }}' as cost_group,
                        '{{ cost_table }}' as cost_table,
                        account_type,
                        account_name,
                        cost
                    from {{ ref(cost_table) }}
                    where {{ product.where("cost_date", "cost_date") }}
                    {%- if not loop.last %}
                        union all
                    {% endif %}
                {% endfor %}
                {%- if not loop.last %}
                    union all
                {% endif %}
            {% endfor %}
        ),

        attributed as (
            select
                attributed_cost_date as cost_date,
                {% if adapter.type() == "clickhouse" -%}
                    arrayJoin(cost_ids) AS cost_id,
                {% elif adapter.type() == "bigquery" -%}
                    cost_id,
                {% endif %}
                sum(attributed_cost / {{ product.get_operator("arrayLength", "cost_ids") }}) as attributed_cost
            from {{ ref("int__" ~ name ~ "_cost_attribution") }}
            {% if adapter.type() == "bigquery" -%}
                cross join unnest(cost_ids) as cost_id
            {% endif %}
            where
                event_id not like 'unattributed_%' and
                {{ product.where("attributed_cost_date", "attributed_cost_date") }}
            group by all
        ),

        non_attributed as (
            select
                attributed_cost_date as cost_date,
                {% if adapter.type() == "clickhouse" -%}
                    arrayJoin(cost_ids) AS cost_id,
                {% elif adapter.type() == "bigquery" -%}
                    cost_id,
                {% endif %}
                sum(attributed_cost) as non_attributed_cost
            from {{ ref("int__" ~ name ~ "_cost_attribution") }}
            {% if adapter.type() == "bigquery" -%}
                cross join unnest(cost_ids) as cost_id
            {% endif %}
            where
                event_id like 'unattributed_%' and
                {{ product.where("attributed_cost_date", "attributed_cost_date") }}
            group by all
        ),

        group_attributed as (
            {%- for cost_group  in cost_groups %}
                select
                    attributed_cost_date as cost_date,
                    {% if adapter.type() == "clickhouse" -%}
                        arrayJoin(cost_ids) AS cost_id,
                    {% elif adapter.type() == "bigquery" -%}
                        cost_id,
                    {% endif %}
                    '{{ cost_group }}' as cost_group,
                    sum(attributed_cost) as attributed_cost
                from {{ ref("int__" ~ name ~ "_" ~ cost_group  ~ "_cost_attribution") }}
                {% if adapter.type() == "bigquery" -%}
                    cross join unnest(cost_ids) as cost_id
                {% endif %}
                where {{ product.where("attributed_cost_date", "attributed_cost_date") }}
                group by all
                {%- if not loop.last %}
                    union all
                {% endif %}
            {% endfor %}
        ),

        result as (
            select
                c.cost_date as cost_date,
                c.cost_group as cost_group,
                c.cost_table,
                c.account_type,
                c.account_name,
                round(sum(c.cost), 2) as source_cost,
                round(sum(ga.attributed_cost), 2) as group_attributed_cost,
                round(sum(a.attributed_cost), 2) as attributed_cost,
                round(sum(na.non_attributed_cost), 2) as non_attributed_cost,
                round(sum(c.cost - (a.attributed_cost + na.non_attributed_cost)), 2) as not_found_cost
            from cost_base c
            left join attributed a using(cost_id, cost_date)
            left join non_attributed na using(cost_id, cost_date)
            left join group_attributed ga using(cost_id, cost_date)
            group by all
            order by 1, 2, 3, 4, 5
        )
        select *
        from result

{% endmacro %}

macro.product.monthly_cost.macro_sql:
{% macro monthly_cost(name) %}

    {%- set model_name = this.name -%}
    {# Проверяем, что имя корректное #}
    {%- if model_name != "int__" ~ name ~ "_monthly_cost" -%}
        {{
            exceptions.raise_compiler_error(
                "Имя модели должно быть с 'int__"
                ~ name
                ~ "_monthly_cost'. Получено: "
                ~ model_name
            )
        }}
    {%- endif -%}
    {% set calc_depth = var("product").get("cost", {}).get("depth", 7) %}
    -- Получаем интервал обработки данных по столбцу "event_date"
    {% set processing_interval = product.get_processing_interval(
        "cost_date", min_processing_interval=calc_depth
    ) %}

    {% set dt = modules.datetime %}
    {% set next_month = processing_interval["to"].replace(day=1) + dt.timedelta(days=32) %}
    {% set processing_day_last = next_month.replace(day=1) - dt.timedelta(days=1) %}
    {% set processing_day_first = processing_interval["from"].replace(day=1) %}

    {%- set agg_ref = ref("int__monthly_costs_aggregated") -%}
    {%- call statement("column_groups", fetch_result=True) -%}
        with
            columns as (
                select distinct
                    {% for col in var("product").get("basic_columns") %}
                        if({{ col }} = '', '', '{{ col }}') as {{ col }}
                        {% if not loop.last %}, {% endif %}
                    {% endfor %}
                from {{ agg_ref }}
                where
                    {{ product.get_operator("toStartOfMonth", "cost_date")}}
                        between '{{ processing_day_first }}' AND '{{ processing_day_last }}'
                    and cost > 0

            ),
            result as (
                select
                    {% if adapter.type() == "clickhouse" %}
                        arrayStringConcat(
                            arrayFilter(
                                x -> notEmpty(x),
                                [
                                    utm_source,
                                    utm_medium,
                                    utm_campaign,
                                    utm_term,
                                    utm_content
                                ]
                            ),
                            ','
                        ) as column_group
                    {% elif adapter.type() == "bigquery" %}
                        ARRAY_TO_STRING(
                            ARRAY(
                                select x
                                from UNNEST([
                                    utm_source,
                                    utm_medium,
                                    utm_campaign,
                                    utm_term,
                                    utm_content
                                ]) as x
                                where x is not null and x != ''
                            ),
                            ','
                        ) as column_group
                    {% endif %}
                from columns
            )
        select *
        from result
    {%- endcall -%}
    {%- set column_groups = load_result("column_groups")["data"] -%}
    {% set all_columns = var("product").get("basic_columns") %}
    {%- set events_ref = ref("int__" + name + "_events") -%}
    {% if not column_groups %}
        with
            result as (
                select
                    {{ product.get_operator("toDate", "'1970-01-01'") }} as cost_date,
                    'monthly' as account_name,
                    'monthly' as account_type,
                    '{{ this }}' as data_source,
                    {{ product.basic_columns(is_empty=True) }},
                    {% if adapter.type() == "clickhouse" %}
                        toLowCardinality(cost_date || '_' || 'empty_monthly') as cost_id,  -- Генерируем уникальный идентификатор для затрат
                    {% elif adapter.type() == "bigquery" %}
                        '1970-01-01' || '_' || 'empty_monthly' as cost_id,
                    {% endif %}
                    0 as impressions,
                    0 as clicks,
                    cast(0.0 as Float64) as cost,
                    0 as is_fake
                limit 0
            )

    {% else %}
        with
            events_data as (
                select *
                from {{ events_ref }} e
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else %}
                        {{ product.get_operator("toStartOfMonth", "event_date")}}
                            between '{{ processing_day_first }}' AND '{{ processing_day_last }}'
                    {% endif %}
            ),
            costs as (
                select *
                from {{ ref("int__monthly_costs_aggregated") }}
                where
                    {{ product.get_operator("toStartOfMonth", "cost_date")}}
                        between '{{ processing_day_first }}' AND '{{ processing_day_last }}'
            ),
            {% for column_group in column_groups %}
                column_group_{{ loop.index }}_costs as (
                    select
                        {{ product.get_operator("toStartOfMonth", "cost_date")}} as cost_date,
                        {% for col in column_group[0].split(",") %}
                            {{ col }}, {% endfor %} array_agg(row_id) as cost_ids,
                        sum(cost) as cost
                    from costs
                    where
                        {% for col in column_group[0].split(",") %}
                            {{ col }} != '' {% if not loop.last %} and {% endif %}
                        {% endfor %}
                        {% for col in all_columns -%}
                            {% if col not in column_group[0].split(",") %}
                                and {{ col }}= ''
                            {% endif %}
                        {%- endfor %}
                        {{
                            dbt_utils.group_by(
                                1 + (column_group[0].split(",") | length)
                            )
                        }}
                ),
                column_group_{{ loop.index }}_events as (
                    select
                        event_date,
                        {{ product.get_operator("toStartOfMonth", "event_date")}} as cost_date,
                        {% for col in column_group[0].split(",") %}
                            {{ col }},
                        {% endfor %}
                        1 as has_events
                    from events_data
                    where
                        true
                        {% for col in column_group[0].split(",") %}
                            and {{ col }} != ''
                        {% endfor %}
                        {{
                            dbt_utils.group_by(
                                2 + (column_group[0].split(",") | length)
                            )
                        }}
                ),
                column_group_{{ loop.index }}_aggregated_costs as (
                    select
                        if(
                            session.event_date = '1970-01-01',
                            cost.cost_date,
                            session.event_date
                        ) as cost_date,
                        {% for col in all_columns -%}
                            {% if col in column_group[0].split(",") %} cost.{{ col }},
                            {% else %} '' as {{ col }},
                            {% endif %}
                        {%- endfor %}
                        coalesce(has_events, 0) as has_events,
                        {% if adapter.type() == "clickhouse" %}
                            arrayDistinct(arrayFlatten(groupArray(cost_ids))) as cost_ids,
                        {% elif adapter.type() == "bigquery" %}
                            ARRAY_CONCAT_AGG(cost_ids) as cost_ids,
                        {% endif %}
                        {{ product.get_operator("any", "cost.cost") }} as cost,
                        0 as is_fake
                    from column_group_{{ loop.index }}_costs as cost
                    left join
                        column_group_{{ loop.index }}_events as session
                        on cost.cost_date = session.cost_date
                        {% for col in column_group[0].split(",") %}
                            and cost.{{ col }} = session.{{ col }}
                        {% endfor %}
                        {{ dbt_utils.group_by(7) }}
                ),

            {% endfor %}
            missing_cost_ids as (
                {% for column_group in column_groups %}
                    {% if adapter.type() == "clickhouse" %}
                        select distinct arrayJoin(cost_ids) as cost_id
                        from column_group_{{ loop.index }}_aggregated_costs
                    {% elif adapter.type() == "bigquery" %}
                        select distinct cost_id
                        from column_group_{{ loop.index }}_aggregated_costs, unnest(cost_ids) as cost_id
                    {% endif %}
                    where has_events <> 1
                    {% if not loop.last %}
                        union distinct
                    {% endif %}
                {% endfor %}
            ),

            missing_costs as (

                select
                    {% if adapter.type() == "clickhouse" %}
                        arrayJoin(
                            arrayMap(
                                x -> toDate(x),
                                range(
                                    toUnixTimestamp(costs.cost_date),
                                    toUnixTimestamp(
                                        least(today(), toLastDayOfMonth(costs.cost_date))
                                    )
                                    + 86400,
                                    86400
                                )
                            )
                        ) as cost_date,
                        if(
                            {{ product.get_operator("toStartOfMonth", "today()")}} > cost_date,
                            costs.cost,
                            costs.cost
                            * toDayOfMonth(today())
                            / toDayOfMonth(toLastDayOfMonth(today()))
                        ) as cost,
                    {% elif adapter.type() == "bigquery" %}
                        day as cost_date,
                        IF(
                            DATE_TRUNC(CURRENT_DATE(), MONTH) > day,
                            costs.cost,
                            costs.cost * EXTRACT(DAY FROM CURRENT_DATE()) / EXTRACT(DAY FROM LAST_DAY(CURRENT_DATE()))
                        ) as cost,
                    {% endif %}

                    {{ product.basic_columns(alias="costs") }},
                    1 as has_events,
                    1 as is_fake
                from missing_cost_ids
                inner join costs on missing_cost_ids.cost_id = costs.row_id
                {% if adapter.type() == "bigquery" %}
                cross join UNNEST(
                    GENERATE_DATE_ARRAY(
                        costs.cost_date,
                        LEAST(
                            CURRENT_DATE(),
                            CAST(DATE_TRUNC(DATE_ADD(costs.cost_date, INTERVAL 1 MONTH), MONTH) - INTERVAL 1 DAY AS DATE)
                        )
                    )
                ) as day
                {% endif %}
            ),
            all_costs as (
                {% for column_group in column_groups %}
                    select
                        cost_date,
                        {{ product.basic_columns() }},
                        has_events,
                        cost,
                        is_fake
                    from column_group_{{ loop.index }}_aggregated_costs
                    where has_events = 1
                    union all
                {% endfor %}
                select
                    cost_date,
                    {{ product.basic_columns() }},
                    has_events,
                    cost,
                    is_fake
                from missing_costs
            ),
            empty_days as (
                select
                    date as attributed_cost_date,
                    'monthly_empty' as account_name,
                    'monthly' as account_type,
                    '{{ this }}' as data_source,
                    {{ product.basic_columns(is_empty=True) }},
                    'monthly_empty' || {{ product.get_operator("toString", "date")}} as cost_id,
                    0 as impressions,
                    0 as clicks,
                    0 as cost,
                    0 as is_fake
                from
                {% if adapter.type() == "clickhouse" %}
                    (
                        select
                            toDate('{{ processing_day_first }}')
                            + number as date
                        from
                            numbers(
                                dateDiff(
                                    'day',
                                    toDate('{{ processing_day_first }}'),
                                    toDate('{{ processing_day_last }}')
                                )
                                + 1
                            )
                    )
                {% elif adapter.type() == "bigquery" %}
                    UNNEST(
                        GENERATE_DATE_ARRAY(
                            DATE('{{ processing_day_first }}'),
                            DATE('{{ processing_day_last }}')
                        )
                    ) AS date
                {% endif %}
                {% if processing_interval["is_updated"] %} where false
                {% endif %}
            ),
            result as (
                select
                    cost_date,
                    'monthly' as account_name,
                    'monthly' as account_type,
                    '{{ this }}' as data_source,
                    {{ product.basic_columns(is_low_cardinality=True) }},
                    {% if adapter.type() == "clickhouse" %}
                        toLowCardinality(
                    {% endif %}
                    concat(
                        cost_date,
                        '_',
                        'monthly',
                        '_',
                        utm_source,
                        '/',
                        utm_medium,
                        '/',
                        utm_campaign,
                        '/',
                        utm_content,
                        '/',
                        utm_term
                    {% if adapter.type() == "clickhouse" %}
                        )
                    {% endif %}
                    ) as cost_id,  -- Генерируем уникальный идентификатор для затрат
                    0 as impressions,
                    0 as clicks,
                    cast(
                        cost / count(distinct cost_date) over (
                            partition by
                                {{ product.get_operator("toStartOfMonth", "cost_date")}}, {{ product.basic_columns() }}
                        ) as Float64
                    ) as cost,
                    is_fake
                from all_costs
                union all
                select *
                from empty_days
            )
    {% endif %}
    select *
    from result
{% endmacro %}

macro.product.cost_attribution.macro_sql:
{% macro cost_attribution(name, utm_list, table_count) %}

    -- Проверяем, что имя модели соответствует ожидаемому имени
    -- "int__xxx_cost_attribution"
    {% if this.table != "int__" + name + "_cost_attribution" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be int__"
                ~ name
                ~ "_cost_attribution"
            )
        }}
    {% endif %}
    -- Получаем интервал обработки данных на основе даты затрат
    {% set calc_depth = modules.datetime.date.today().day - 1 %}
    {% if calc_depth < var("product").get("cost", {}).get("depth", 7) %}
        {% set calc_depth = var("product").get("cost", {}).get("depth", 7) %}
    {% endif %}
    {% set processing_interval = product.get_processing_interval(
        "attributed_cost_date", min_processing_interval=calc_depth
    ) %}

    {%- set cfg = var("product") -%}
    {%- set daily_costs = cfg.cost.daily -%}
    {% set relations = [] %}

    {%- set utm_keys = [] -%}
    {%- set utm_sets = [] -%}

    {% for cost in daily_costs -%}
        {%- do relations.append(
            ref("int__" ~ name ~ "_" ~ cost ~ "_cost_attribution")
        ) -%}
        {%- for item in daily_costs.get(cost).utm_keys -%}
            {%- do utm_sets.append(item | join(",")) -%}
            {%- for k in item -%} {%- do utm_keys.append(k) -%} {%- endfor -%}
        {%- endfor -%}
    {% endfor %}
    {% set mca_ref = ref("int__monthly_costs_aggregated") %}
    {% if var("product").get("cost", {}).get("monthly", []) | length > 0 -%}
        {%- do relations.append(ref("int__" ~ name ~ "_monthly_cost_attribution")) -%}
        {%- call statement("column_groups", fetch_result=True) -%}
            with
                columns as (
                    select distinct
                        {% for col in var("product").get("basic_columns") %}
                            if({{ col }} = '', '', '{{ col }}') as {{ col }}
                            {% if not loop.last %}, {% endif %}
                        {% endfor %}
                    from {{ mca_ref }}
                    where
                    {% if adapter.type() == "clickhouse" -%}
                        toStartOfMonth(cost_date)
                        between toStartOfMonth(
                            toDate('{{ processing_interval["from"] }}')
                        ) and toLastDayOfMonth(
                            toDate('{{ processing_interval["to"] }}')
                        )
                    {% elif adapter.type() == "bigquery" -%}
                        date_trunc(cost_date, MONTH)
                          between
                            date_trunc(date('{{ processing_interval["from"] }}'), month)
                            and last_day(date('{{ processing_interval["to"] }}'))
                    {% endif %}
                        and cost > 0

                ),
                result as (
                    select
                    {% if adapter.type() == "clickhouse" %}
                        arrayStringConcat(
                            arrayFilter(
                                x -> notEmpty(x),
                                [
                                    utm_source,
                                    utm_medium,
                                    utm_campaign,
                                    utm_term,
                                    utm_content
                                ]
                            ),
                            ','
                        ) as column_group
                    {% elif adapter.type() == "bigquery" %}
                        ARRAY_TO_STRING(
                            ARRAY(
                                select x
                                from UNNEST([
                                    utm_source,
                                    utm_medium,
                                    utm_campaign,
                                    utm_term,
                                    utm_content
                                ]) as x
                                where x is not null and x != ''
                            ),
                            ','
                        ) as column_group
                    {% endif %}
                    from columns
                )
            select *
            from result
        {%- endcall -%}
        {%- set column_groups = load_result("column_groups")["data"] -%}
        {% for gr in column_groups %}
            {%- do utm_sets.append(gr[0]) -%}
            {% for k in gr[0].split(",") %} {%- do utm_keys.append(k) -%} {% endfor %}
        {% endfor %}
    {% endif %}
    {%- set unique_utm_sets = utm_sets | unique | list -%}
    {%- set unique_utm_keys = utm_keys | unique | list -%}
    with
        attributed_cost_data as (
            {% for tbl in relations %}
                select
                    attributed_cost_date,
                    event_id,
                    cost_ids,
                    attributed_cost,
                    attributed_impressions,
                    attributed_clicks
                from {{ tbl }}
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else %}
                        attributed_cost_date
                        between '{{ processing_interval["from"] }}'
                        and '{{ processing_interval["to"] }}'
                    {% endif %}
                {% if not loop.last %}
                    union all
                {% endif %}
            {% endfor %}
        ),
        events_filtered as (

            select e.event_date as attributed_cost_date, e.event_id
            from {{ ref("int__" + name + "_events") }} e
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    e.event_date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
                and (
                    {%- for sub in unique_utm_sets -%}
                        (
                            {%- for item in sub.split(",") %}
                                {{ item }}!= '' {% if not loop.last %} and {% endif %}
                            {% endfor -%}
                        )
                        {% if not loop.last %} or {% endif %}
                    {%- endfor -%}
                )
        ),
        attributed_costs as (
            select
                e.attributed_cost_date,
                e.event_id,
                {% if adapter.type() == "clickhouse" %}
                    arrayDistinct(arrayFlatten(groupArray(cost_ids))) as cost_ids,
                {% elif adapter.type() == "bigquery" %}
                    ARRAY_CONCAT_AGG(cost_ids) as cost_ids,
                {% endif %}
                sum(c.attributed_impressions) as attributed_impressions,
                sum(c.attributed_clicks) as attributed_clicks,
                sum(c.attributed_cost) as attributed_cost
            from events_filtered as e
            inner join attributed_cost_data as c using (attributed_cost_date, event_id)
            group by attributed_cost_date, event_id

        ),
        unattributed_costs as (
            select distinct
                cost_date as attributed_cost_date,
                'unattributed_' || cost_id as event_id,
                [cost_id] as cost_ids,
                impressions as attributed_impressions,
                clicks as attributed_clicks,
                cost as attributed_cost
            from {{ ref("int__" ~ name ~ "_cost_attribution_non_attributed") }}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    cost_date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
        ),
        empty_days as (
            select
                date as attributed_cost_date,
                'cost_attribution_empty_' || date as event_id,
                {{ product.get_operator('[]')}} as cost_ids,
                0.0 as attributed_cost,
                0.0 as attributed_impressions,
                0.0 as attributed_clicks
            from
            {% if adapter.type() == "clickhouse" %}
                (
                    select toDate('{{ processing_interval["from"] }}') + number as date
                    from
                        numbers(
                            dateDiff(
                                'day',
                                toDate('{{ processing_interval["from"] }}'),
                                toDate('{{ processing_interval["to"] }}')
                            )
                            + 1
                        )
                )
            {% elif adapter.type() == "bigquery" %}
                unnest(
                    generate_date_array(
                        DATE('{{ processing_interval["from"] }}'),
                        DATE('{{ processing_interval["to"] }}')
                    )
                ) AS date
            {% endif %}
            {% if processing_interval["is_updated"] %} where false {% endif %}
        ),
        result as (
            select *
            from attributed_costs
            union all
            select *
            from unattributed_costs
            union all
            select *
            from empty_days
        )

    select distinct *
    from result
{% endmacro %}

macro.product.cost_attribution_non_attri.macro_sql:
{% macro cost_attribution_non_attributed(name, utm_list, table_count) %}

    {% if this.table != "int__" + name + "_cost_attribution_non_attributed" %}
        {{
            exceptions.raise_compiler_error(
                "Invalid model name. Got: "
                ~ this.table
                ~ ". Should be int__"
                ~ name
                ~ "_cost_attribution_non_attributed"
            )
        }}
    {% endif %}
    -- Получаем интервал обработки данных на основе даты затрат
    {% set calc_depth = modules.datetime.date.today().day - 1 %}
    {% if calc_depth < var("product").get("cost", {}).get("depth", 7) %}
        {% set calc_depth = var("product").get("cost", {}).get("depth", 7) %}
    {% endif %}
    {% set processing_interval = product.get_processing_interval(
        "cost_date", min_processing_interval=calc_depth
    ) %}
    {%- set cfg = var("product") -%}
    {%- set daily_costs = cfg.cost.daily -%}
    {% set relations = [] %}
    {% set cost_tables = [] %}
    {% for cost_item in daily_costs -%}
        {%- do relations.append(
            ref("int__" ~ name ~ "_" ~ cost_item ~ "_cost_attribution")
        ) -%}
        {% for cost_table in daily_costs[cost_item].tables -%}
            {%- do cost_tables.append(ref(cost_table)) -%}
        {% endfor %}
    {% endfor %}
    with

        used_cost_ids as (
            {% for table in relations -%}
                {% if adapter.type() == "clickhouse" %}
                    select arrayJoin(cost_ids) as cost_id
                    from {{ table }}
                {% elif adapter.type() == "bigquery" %}
                    select cost_id
                    from {{ table }} t
                    cross join unnest(t.cost_ids) as cost_id
                {% endif %}
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else %}
                        attributed_cost_date
                        between '{{ processing_interval["from"] }}'
                        and '{{ processing_interval["to"] }}'
                    {% endif %}
                {% if not loop.last %}
                    union all
                {% endif %}
            {% endfor %}
            {% if var("product").get("cost", {}).get("monthly", []) | length > 0 -%}
                union all
                {% if adapter.type() == "clickhouse" %}
                    select arrayJoin(cost_ids) as cost_id
                    from {{ ref("int__" ~ name ~ "_monthly_cost_attribution") }}
                {% elif adapter.type() == "bigquery" %}
                    select cost_id
                    from {{ ref("int__" ~ name ~ "_monthly_cost_attribution") }} t
                    cross join unnest(t.cost_ids) as cost_id
                {% endif %}
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else %}
                        attributed_cost_date
                        between '{{ processing_interval["from"] }}'
                        and '{{ processing_interval["to"] }}'
                    {% endif %}
            {% endif %}
        ),
        cost_model_tables as (

            {% for cost_table in cost_tables -%}
                select
                    cm.cost_id,
                    cm.cost_date,
                    cm.account_name,
                    cm.account_type,
                    {{ product.basic_columns() }},
                    {{ product.get_operator("toFloat", "cm.impressions") }} as impressions,
                    {{ product.get_operator("toFloat", "cm.clicks") }} as clicks,
                    {{ product.get_operator("toFloat", "cm.cost") }} as cost
                from {{ cost_table }} as cm
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else %}
                        cost_date
                        between '{{ processing_interval["from"] }}'
                        and '{{ processing_interval["to"] }}'
                    {% endif %}
                {% if not loop.last %}
                    union all
                {% endif %}
            {% endfor %}
            {% if var("product").get("cost", {}).get("monthly", []) | length > 0 -%}
                union all
                select
                    cm.cost_id,
                    cm.cost_date,
                    cm.account_name,
                    cm.account_type,
                    {{ product.basic_columns() }},
                    {{ product.get_operator("toFloat", "cm.impressions") }} as impressions,
                    {{ product.get_operator("toFloat", "cm.clicks") }} as clicks,
                    {{ product.get_operator("toFloat", "cm.cost") }} as cost
                from {{ ref("int__" ~ name ~ "_monthly_cost") }} as cm
                where
                    {% if processing_interval["is_updated"] %} false
                    {% else %}
                        cost_date
                        between '{{ processing_interval["from"] }}'
                        and '{{ processing_interval["to"] }}'
                    {% endif %}
            {% endif %}
        ),
        cost_model_filtered as (
            select cm.*
            from cost_model_tables as cm
            {% if adapter.type() == "clickhouse" %}
                anti join used_cost_ids using (cost_id)
            {% elif adapter.type() == "bigquery" %}
                where not exists (
                    select 1
                    from used_cost_ids u
                    where u.cost_id = cm.cost_id
                )
            {% endif %}
        ),
        empty_days as (
            select
                'non_attributed_empty_' || date as cost_id,
                date as cost_date,
                'empty_cost' as account_name,
                'empty_cost' as account_type,
                {{ product.basic_columns(is_empty=True) }},
                0.0 as impressions,
                0.0 as clicks,
                0.0 as cost
            from
                (
                    {% if adapter.type() == "clickhouse" %}
                        select toDate('{{ processing_interval["from"] }}') + number as date
                        from
                            numbers(
                                dateDiff(
                                    'day',
                                    toDate('{{ processing_interval["from"] }}'),
                                    toDate('{{ processing_interval["to"] }}')
                                )
                                + 1
                            )
                    {% elif adapter.type() == "bigquery" %}
                        select
                            DATE_ADD(
                                DATE '{{ processing_interval["from"] }}',
                                interval day_offset DAY
                            ) as date
                        from
                            UNNEST(
                                GENERATE_ARRAY(
                                    0,
                                    DATE_DIFF(
                                        DATE '{{ processing_interval["to"] }}',
                                        DATE '{{ processing_interval["from"] }}',
                                        DAY
                                    )
                                )
                            ) as day_offset
                    {% endif %}
                )
            {% if processing_interval["is_updated"] %} where false {% endif %}
        ),
        result as (
            select *
            from cost_model_filtered
            union all
            select *
            from empty_days
        )

    select *
    from result
{% endmacro %}

macro.product.compare_tables.macro_sql:
{% macro compare_tables(
    table_left,
    table_right,
    group_columns=[],
    dimensions=[],
    metrics=[],
    date_from=None,
    date_to=None,
    date_column=None,
    where_expr='',
    dimension_agg='count(1)',
    top_count=3
) %}

    {%- set group_by = group_columns | join(', ') -%}
    {% set tables = {"l": table_left, "r": table_right} %}

    with
        {% for alias, table in tables.items() %}
            {{ alias }}_base as (
                select
                    {{ group_by }},
                    {%- for dimension in dimensions -%}
                        coalesce(nullif({{ dimension }}, ''), 'null') as {{ dimension }},
                    {% endfor %}
                    {{ metrics | join(', ') }},
                    count(1) over() as all_cnt,
                    {{ dimension_agg }} over() as all_agg
                from {{ table }}
                where
                    {{ date_column }} >= '{{ date_from }}' and
                    {{ date_column }} <= '{{ date_to }}'
                    {%- if where_expr %}and {{ where_expr }}{% endif %}
            ),

            {%- for dimension in dimensions -%}
                {{ alias }}_{{ dimension }} as (
                        select
                            {{ group_by }},
                            {{ dimension }},
                            {{ dimension_agg }} as cnt
                        from {{ alias }}_base
                        group by {{ group_by }}, {{ dimension }}
                        qualify row_number() over(partition by {{ group_by }} order by {{ dimension_agg }} desc) <= {{ top_count }}
                        order by {{ dimension_agg }} desc, {{ dimension }}
                ),
                {{ alias }}_{{ dimension }}_agg as (
                    select
                       {{ group_by }},
                       array_agg(
                            {{ dimension }} || ' — ' || cnt
                            order by cnt desc, {{ dimension }}
                       ) as {{ dimension }}_top
                    from {{ alias }}_{{ dimension }}
                    group by {{ group_by }}
                ),
            {% endfor %}

            {{ alias }} as (
                select
                    {% for metric in metrics -%}
                        sum({{ metric }}) as {{ metric }}_sum,
                    {% endfor %}
                    {%- for dimension in dimensions -%}
                        count(distinct {{ dimension }}) as {{ dimension }}_cnt,
                        {{ alias }}_{{ dimension }}_agg.{{ dimension }}_top as {{ dimension }}_top,
                    {% endfor %}
                    all_cnt,
                    {{ dimension_agg }} as group_agg,
                    array_to_string([{{ group_by }}], '__') as grouped_by
                from {{ alias }}_base
                {% for dimension in dimensions %}
                    left join {{ alias }}_{{ dimension }}_agg using({{ group_by }})
                {% endfor %}
                group by {{ group_by }}, {%- for dimension in dimensions -%} {{ dimension }}_top, {% endfor %} all_cnt
            ),
        {% endfor %}

        result as (
            select
                {% for table_alias in tables %}
                    max({{ table_alias }}.all_cnt) over() as {{ table_alias }}_all_cnt,
                {% endfor %}

                coalesce(l.grouped_by, r.grouped_by) as `{{ group_columns | join('_') }}`,

                {% for table_alias in tables %}
                    {{ table_alias }}.group_agg as {{ table_alias }}_group_agg,
                {% endfor %}

                {%- for dimension in dimensions -%}
                    {% for table_alias in tables %}
                        {{ table_alias }}.{{ dimension }}_cnt as {{ table_alias }}_{{ dimension }}_cnt,
                    {% endfor %}

                    {% for table_alias in tables %}
                        {{ table_alias }}.{{ dimension }}_top as {{ table_alias }}_{{ dimension }}_top,
                    {% endfor %}
                {% endfor %}

                {%- for metric in metrics -%}
                    {% for table_alias in tables %}
                        {% set col = table_alias ~ '.' ~ metric ~ '_sum' %}
                        case
                            when {{ col }} >= 1000000000 THEN FORMAT("%.1fB", {{ col }} / 1000000000)
                            when {{ col }} >= 1000000 THEN FORMAT("%.1fM", {{ col }} / 1000000)
                            when {{ col }} >= 1000 THEN FORMAT("%.1fK", {{ col }} / 1000)
                            else cast({{ col }} as string)
                        end as {{ table_alias }}_{{ metric }}_sum,
                    {% endfor %}

                    concat(
                        cast(
                            round(
                                safe_divide(
                                    coalesce(r.{{ metric }}_sum, 0) - l.{{ metric }}_sum,
                                    l.{{ metric }}_sum
                                ) * 100,
                                0
                            ) as string
                        ),
                        '%'
                    ) as {{ metric }}_sum_diff,
                    concat(
                        cast(
                            round(
                                safe_divide(
                                    coalesce(r.{{ metric }}_sum, 0) - l.{{ metric }}_sum,
                                    sum(l.{{ metric }}_sum) over()
                                ) * 100,
                                0
                            ) as string
                        ),
                        '%'
                    ) as {{ metric }}_sum_total_diff,
                {% endfor %}

            from l
            full outer join r using(grouped_by)
            order by 1
        )
    select * from result
    order by {{ group_columns | join('_') }}

{% endmacro %}

macro.product.compare_tables_utms.macro_sql:
{% macro compare_tables_utms(table_name, columns, date_from, date_to, date_column, where_expr="") %}
    with
        base as (
            select
                {{ columns | join(", ")}},
                count(1) over() as all_cnt
            from {{ table_name }}
            where {{ date_column }} between '{{ date_from }}' and '{{ date_to }}'
        ),
        utms as (
            select
                {% for col in columns %}
                    if({{ col }} = '', '', '{{ col }}') as {{ col }},
                {% endfor %}
                count(1) over() as filtered_cnt,
                all_cnt
            from base
            where {{ where_expr }}
        ),
        result as (
            select
                {% if adapter.type() == "clickhouse" %}
                    arrayStringConcat(
                        arrayFilter(
                            x -> notEmpty(x),
                            [
                                {{ columns | join(", ")}}
                            ]
                        ),
                        ', '
                    ) as column_group
                {% elif adapter.type() == "bigquery" %}
                    array_to_string(
                        array(
                            select x
                            from unnest([
                                {{ columns | join(", ")}}
                            ]) as x
                            where x is not null and x != ''
                        ),
                        ', '
                    ) as column_group,
                {% endif %}
                format("%'d", count(1)) as matched_cnt,
                format("%'d", filtered_cnt) as filtered_cnt,
                format("%'d", all_cnt) as all_cnt
            from utms
            group by column_group, filtered_cnt, all_cnt
            order by length(column_group)
        )
    select *
    from result

{% endmacro %}

