    {% if var("cohort")["values"] %} {{ var("cohort")["values"] }}  -- a
    {% else %} {{ source("mh", "values") }}  -- b
    {% endif %} as v
left join
    {% if var("cohort")["costs"] %} {{ var("cohort")["costs"] }}
    {% else %} {{ source("mh", "attributed_cost") }}
    {% endif %} as c on v.sessionid = c.event_id
where
    v.transactionid != '(not set)' and v.value_lc = 1
    {% if is_incremental() %} and v.transaction_date >= "{{max_ts}}" {% endif %}

