{{
    config(
        materialized="incremental",
        partition_by=["toYYYYMMDD(transaction_time)"],
        order_by=[
            "transaction_time",
            "transaction_id",
        ],
        incremental_strategy="insert_overwrite",
        ttl="toDate(transaction_time) + INTERVAL 30 DAY TO DISK 'object_storage'",
        enabled=(
            var("events", {}).get("metrika", {}).get("enabled", false)
            and var("events").get("metrika", {}).get("transactions", false)
        ),
    )
}}

{% set processing_interval = get_processing_interval("toDate(transaction_time)") %}
with
    data as (
        {% if var("events")["metrika"]["datasource"] == "metrika_pro" %}
        {% elif var("events")["metrika"]["datasource"] == "logs_api" %}

            select distinct
                'Metrika' as transaction_source,
                'purchase' as transaction_name,
                cast(client_id as String) as user_id,
                arrayJoin(purchase_id) as transaction_id,
                arrayJoin(purchase_date_time) as transaction_time,
                arrayJoin(purchase_revenue) as revenue
            from {{ ref(var("events")["metrika"]["table"]) }}
            where
                {% if processing_interval["is_updated"] %} false
                {% else %}
                    date
                    between '{{ processing_interval["from"] }}'
                    and '{{ processing_interval["to"] }}'
                {% endif %}
        {% else %}
        {% endif %}
    ),
    time_fix as (
        select
            transaction_source,
            transaction_name,
            user_id,
            transaction_id,
            if(
                toDate(transaction_time) <= '{{ processing_interval["to"] }}',
                transaction_time,
                toDateTime(concat('{{ processing_interval["to"] }}', ' ', '23:59:59'))
            ) as transaction_time,
            revenue
        from data
    ),
    result as (
        select *
        from time_fix
        qualify
            row_number() over (partition by transaction_id order by transaction_time)
            = 1
    )
select *
from result

